	/** Folder migration can touch disk, so it runs on RuneLite's worker. */
	private synchronized void prepareFolder()
	{
		if (preparingFolder || folder != null) { return; }
		preparingFolder = true;
		notice = "Preparing the recording folder…";
		executor.execute(() ->
		{
			try
			{
				folder = getPluginDirectory();
				viewer.folder(folder);
				notice = "Ready to record.";
			}
			catch (IOException | RuntimeException e)
			{
				notice = "Could not prepare the recording folder: " + rootMessage(e)
					+ "\nPress Start recording to retry.";
			}
			finally { preparingFolder = false; }
		});
	}

	String folderPath()
	{
		return folder == null ? "The recording folder is not ready yet." : folder.toString();
	}

	boolean canRecover()
	{
		return saveFailed(pendingSave);
	}

	private static boolean saveFailed(OsrsCapture pending)
	{
		return pending != null && pending.recorder().state() == Recorder.State.FAILED;
	}

	void retrySave()
	{
		clientThread.invoke(() ->
		{
			if (canRecover())
			{
				handingOff = true;
				watchSave(pendingSave, pendingSave.recorder().finish());
			}
		});
	}

	void discardSave()
	{
		clientThread.invoke(() ->
		{
			if (canRecover())
			{
				((MccrFileRecorder) pendingSave.recorder()).discard();
				pendingSave = null;
				save = CompletableFuture.completedFuture(null);
				notice = "Unsaved recording discarded.";
			}
		});
	}

	/** The side panel's button and the hotkey: nothing while the button is greyed out. */
	void toggleRecording()
	{
		PanelState state = panelState();
		if (!state.canToggle)
		{
			return;
		}
		if (state.recording)
		{
			stopRecording();
		}
		else
		{
			startRecording();
		}
	}

	void startRecording()
	{
		stopped = false;
		manual = true;
		if (folder == null) { prepareFolder(); }
		clientThread.invoke(() ->
		{
			if (capture == null && client.getGameState() == GameState.LOGGED_IN)
			{
				beginCapture();
			}
		});
	}

	void stopRecording()
	{
		stopped = true;
		manual = false;
		continuing = false;
		clientThread.invoke(() -> endCapture("stopped by you", false));
	}

	PanelState panelState()
	{
		OsrsCapture current = capture;
		List<SavedFile> files = new ArrayList<>(saved);
		StringBuilder text = new StringBuilder();
		if (current == null)
		{
			OsrsCapture pending = pendingSave;
			boolean recover = saveFailed(pending);
			boolean resume = resumes();
			text.append(handingOff ? "Saving your recording." + (resume ? " Recording resumes after it is saved." : "")
				: recover ? "Recording paused. The unsaved part is kept as a .partial file.\n\n"
					+ pending.recorder().error() + "\n\nRetry saving, or discard it."
				: stopped ? "Not recording." : notice);
			boolean in = loggedIn;
			if (!in)
			{
				text.append("\n\nLog in to start recording.");
			}
			else if (stopped && pending == null)
			{
				text.append("\n\nWhat you played so far is kept. Press Start recording to begin a new one.");
			}
			return new PanelState(handingOff ? "Saving…" : "Not recording", text.toString(), "", files, handingOff && resume,
				in && !recover && (pending == null || handingOff));
		}
		// The headline carries the time, so only the capture's other states are repeated here.
		String line = current.status();
		if (!line.startsWith("Recording"))
		{
			text.append(line).append("\n\n");
		}
		Recorder recorder = current.recorder();
		if (recorder.state() == Recorder.State.FAILED)
		{
			text.append("Cannot save: ").append(recorder.error());
		}
		else
		{
			text.append("Other players are recorded as unnamed figures.");
		}
		boolean recording = current.recording();
		String headline = recording ? "Recording · " + clock(earlier + current.seconds()) : "Not recording";
		return new PanelState(headline, text.toString(), fileName(recorder, ""), files, recording, recording);
	}

	static String clock(double seconds)
	{
		int s = (int) Math.max(0, seconds);
		return s >= 3600 ? String.format(Locale.ROOT, "%d:%02d:%02d", s / 3600, s / 60 % 60, s % 60)
			: String.format(Locale.ROOT, "%d:%02d", s / 60, s % 60);
	}

	/** Whether recording should go on once the game allows it. */
	private boolean resumes()
	{
		return enabled && !stopped && (manual || continuing || config.recordOnLogin());
	}

	private boolean wantsRecording()
	{
		return resumes() && client.getGameState() == GameState.LOGGED_IN;
	}

	static String fileStem(String playerName)
	{
		String who = playerName == null ? "" : playerName.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "-").replaceAll("^-|-$", "");
		String when = LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd-HHmm"));
		return "osrs-" + when + (who.isEmpty() ? "" : "-" + who);
	}

	private void changeScene()
	{
		WorldView view = client.getTopLevelWorldView();
		sceneIdentity = SceneIdentity.of(view);
		OsrsCapture current = capture;
		if (current != null) { current.sceneChanged(view); }
		rediscover = true;
	}

	private void beginCapture()
	{
		if (!wantsRecording() || capture != null || pendingSave != null || handingOff || folder == null)
		{
			return;
		}
		Player me = client.getLocalPlayer();
		WorldView view = client.getTopLevelWorldView();
		if (view == null || me == null) { return; }
		sceneIdentity = SceneIdentity.of(view);
		String dimension = sceneIdentity.dimension();
		if (series == null)
		{
			series = UUID.randomUUID().toString();
			nextPart = 1;
			earlier = 0;
			pseudonyms.clear();
		}
		// Resolve the filename on the first scene tick, when the character name is available.
		Recorder recorder = new MccrFileRecorder(gson, folder, () ->
		{
			Player who = client.getLocalPlayer();
			return fileStem(who == null ? null : who.getName());
		}, executor);
		OsrsCapture next = new OsrsCapture(client, recorder, config, dimension, me.getName(), client.getWorld(),
			series, nextPart++, pseudonyms, config.chunkMinutes() * 60.0);
		next.account(accountKey());
		capture = next;
		continuing = true;
		rediscover = true;
		notice = "Recording.";
		next.start().whenComplete((ignored, throwable) ->
		{
			if (throwable != null)
			{
				notice = "Could not start the recording file: " + rootMessage(throwable);
				log.debug("capture open failed", throwable);
			}
		});
	}

	/** Opaque account key; the salt lives in plugin settings. */
	private String accountKey()
	{
		String salt = configManager.getConfiguration(EmbertideConfig.GROUP, AccountKey.SALT_KEY);
		if (salt == null || salt.isEmpty())
		{
			salt = AccountKey.newSalt();
			configManager.setConfiguration(EmbertideConfig.GROUP, AccountKey.SALT_KEY, salt);
		}
		return AccountKey.of(salt, client.getAccountHash());
	}

	private CompletableFuture<Void> endCapture(String reason, boolean openStudio)
	{
		OsrsCapture current = capture;
		capture = null;
		if (current == null)
		{
			return save;
		}
		pendingSave = current;
		handingOff = true;
		CompletableFuture<Void> finishing = current.finish(reason, openStudio, true);
		earlier += current.seconds();
		return watchSave(current, finishing);
	}

	private CompletableFuture<Void> watchSave(OsrsCapture current, CompletableFuture<Void> result)
	{
		// Publication is updated before the returned future completes, including on
		// client shutdown when another client-thread callback cannot be relied on.
		save = result.whenComplete((ignored, throwable) ->
		{
			if (throwable == null)
			{
				if (current.recorder().state() == Recorder.State.COMPLETE)
				{
					saved.add(new SavedFile(fileName(current.recorder(), "recording " + current.part()), current.seconds()));
				}
				pendingSave = null;
				notice = current.recorder().state() == Recorder.State.IDLE
					? "Recording cancelled before the first scene." : "Recording saved.";
			}
			else
			{
				notice = "Recording paused: retry saving or discard the unsaved recording.";
				log.warn("Could not save recording", throwable);
			}
			handingOff = false;
		});
		return save;
	}

	private static String fileName(Recorder recorder, String otherwise)
	{
		Filepath path = recorder instanceof MccrFileRecorder ? ((MccrFileRecorder) recorder).path() : null;
		return path == null ? otherwise : path.getFileName().toString();
	}

	private static String rootMessage(Throwable throwable)
	{
		Throwable cause = throwable;
		while (cause.getCause() != null && cause.getCause() != cause)
		{
			cause = cause.getCause();
		}
		return cause.getMessage() == null ? cause.getClass().getSimpleName() : cause.getMessage();
	}

	private static BufferedImage icon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(0xE8, 0x86, 0x3A));
		g.fillOval(2, 2, 12, 12);
		g.setColor(new Color(0xFF, 0xE0, 0xAD));
		g.fillOval(6, 5, 4, 4);
		g.dispose();
		return image;
	}
}

package com.extrinsiccognition.embertide;

import com.google.gson.JsonObject;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.client.util.Text;

/** Allowlisted server game messages, kept only as kind and fields. */
final class GameMessages
{
	static final class Match
	{
		final String kind;
		final JsonObject fields;

		Match(String kind, JsonObject fields)
		{
			this.kind = kind;
			this.fields = fields;
		}
	}

	private static final int MAX_NAME = 64;

	private static final Pattern KILL_COUNT = Pattern.compile(
		"Your (?!.* lap count is: )(?:completion count for |subdued |completed )?((?:[A-Z]|herbiboar).*?) (?:(?:kill|harvest|completion|chest|success) )?count is: ([\\d,]+)\\.?");
	private static final Pattern PERSONAL_BEST = Pattern.compile(
		"(?:.*\\s)?(?:[Dd]uration|[Tt]ime): ([\\d:.]+) \\(new personal best\\)\\.?(?:\\s.*)?");
	private static final Pattern PET_FOLLOWER = Pattern.compile("You have a funny feeling like you're being followed\\.?");
	private static final Pattern PET_BACKPACK = Pattern.compile("You feel something weird sneaking into your backpack\\.?");
	private static final Pattern PET_DUPLICATE = Pattern.compile("You have a funny feeling like you would have been followed\\.*");
	private static final Pattern COLLECTION_LOG = Pattern.compile("New item added to your collection log: (.+?)\\.?");
	private static final Pattern VALUABLE_DROP = Pattern.compile("Valuable drop: (?:([\\d,]+) x )?(.+?) \\(([\\d,]+) coins\\)\\.?");
	private static final Pattern UNTRADEABLE_DROP = Pattern.compile("Untradeable drop: (?:([\\d,]+) x )?(.+?)\\.?");
	private static final Pattern CLUE_COMPLETE = Pattern.compile(
		"You have completed ([\\d,]+) (beginner|easy|medium|hard|elite|master) Treasure Trails?\\.?");
	private static final Pattern COMBAT_TASK = Pattern.compile(
		"(?:CA_ID:\\d+\\|)?Congratulations, you've completed an? (easy|medium|hard|elite|master|grandmaster) combat task(?::.*)?\\.?");
	private static final Pattern SLAYER_TASK = Pattern.compile(
		"You've completed ([\\d,]+) (?:(?:Wildy|Wilderness) )?tasks?(?: and received ([\\d,]+) points?)?(?:[,;].*)?\\.?");
	private static final Pattern QUEST_COMPLETE = Pattern.compile("Congratulations, you've completed a quest: (.+?)\\.?");
	private static final Pattern DIARY_COMPLETE = Pattern.compile(
		"Congratulations! You have completed all of the (easy|medium|hard|elite) tasks in the (.+?) area\\..*");
	private static final Pattern SUPERIOR = Pattern.compile("A superior foe has appeared\\.*");
	private static final Pattern OWN_DEATH = Pattern.compile("Oh dear, you are dead!");

	private GameMessages()
	{
	}

	static Match match(ChatMessageType type, String raw)
	{
		if (raw == null || (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM))
		{
			return null;
		}
		String line = Text.removeTags(raw).replace((char) 160, ' ').trim();
		if (line.isEmpty() || line.length() > 300)
		{
			return null;
		}
		Matcher m;
		if ((m = KILL_COUNT.matcher(line)).matches())
		{
			return found("kill_count", "boss", name(m.group(1)), "count", number(m.group(2)));
		}
		if ((m = PERSONAL_BEST.matcher(line)).matches())
		{
			double seconds = duration(m.group(1));
			return seconds < 0 ? null : found("personal_best", "duration_s", seconds);
		}
		if (PET_FOLLOWER.matcher(line).matches()) { return found("pet", "how", "follower"); }
		if (PET_BACKPACK.matcher(line).matches()) { return found("pet", "how", "backpack"); }
		if (PET_DUPLICATE.matcher(line).matches()) { return found("pet", "how", "duplicate"); }
		if ((m = COLLECTION_LOG.matcher(line)).matches())
		{
			return found("collection_log", "item", name(m.group(1)));
		}
		if ((m = VALUABLE_DROP.matcher(line)).matches())
		{
			return found("valuable_drop", "item", name(m.group(2)), "quantity", quantity(m.group(1)), "value", number(m.group(3)));
		}
		if ((m = UNTRADEABLE_DROP.matcher(line)).matches())
		{
			return found("untradeable_drop", "item", name(m.group(2)), "quantity", quantity(m.group(1)));
		}
		if ((m = CLUE_COMPLETE.matcher(line)).matches())
		{
			return found("clue_complete", "count", number(m.group(1)), "tier", m.group(2));
		}
		if ((m = COMBAT_TASK.matcher(line)).matches())
		{
			return found("combat_task", "tier", m.group(1));
		}
		if ((m = SLAYER_TASK.matcher(line)).matches())
		{
			return found("slayer_task_complete", "tasks", number(m.group(1)), "points", m.group(2) == null ? null : number(m.group(2)));
		}
		if ((m = QUEST_COMPLETE.matcher(line)).matches())
		{
			return found("quest_complete", "quest", name(m.group(1)));
		}
		if ((m = DIARY_COMPLETE.matcher(line)).matches())
		{
			return found("diary_complete", "tier", m.group(1), "area", name(m.group(2)));
		}
		if (SUPERIOR.matcher(line).matches())
		{
			return found("superior_spawn");
		}
		if (OWN_DEATH.matcher(line).matches())
		{
			return found("own_death");
		}
		return null;
	}

	/** Fields as name, value pairs, in order; a null value is left out. */
	private static Match found(String kind, Object... fields)
	{
		JsonObject f = new JsonObject();
		for (int i = 0; i < fields.length; i += 2)
		{
			Object value = fields[i + 1];
			if (value instanceof String) { f.addProperty((String) fields[i], (String) value); }
			else if (value != null) { f.addProperty((String) fields[i], (Number) value); }
		}
		return new Match(kind, f);
	}

	private static long quantity(String value)
	{
		return value == null ? 1 : number(value);
	}

	private static String name(String value)
	{
		String trimmed = value.trim();
		return trimmed.length() > MAX_NAME ? trimmed.substring(0, MAX_NAME) : trimmed;
	}

	private static long number(String value)
	{
		try
		{
			return Long.parseLong(value.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	/** Seconds, or -1 if not a duration. */
	static double duration(String value)
	{
		String[] parts = value.split(":");
		if (parts.length > 3)
		{
			return -1;
		}
		double total = 0;
		try
		{
			for (String part : parts)
			{
				if (part.isEmpty()) { return -1; }
				total = total * 60 + Double.parseDouble(part);
			}
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
		return Math.round(total * 100) / 100.0;
	}
}

package com.extrinsiccognition.embertide;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Constants;
import net.runelite.api.Scene;
import net.runelite.api.SceneTileModel;
import net.runelite.api.SceneTilePaint;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;

/**
 * The loaded scene's ground as the client built it: osrs.ground rows, one per physical plane and band of columns.
 * A tile is 0 (none), a paint [sw, se - sw, ne - sw, nw - sw] with a fifth texture when it has one, or a shaped tile
 * [-shape, rotation, then a, b - a, c - a, texture per face], colours as the client's HSL with 12345678 for hidden.
 * Corner colours of a tile share hue and saturation, so the differences are short.
 * The writer and the viewer's reader of this layout both live here.
 */
public final class GroundRows
{
	/** Tile text per row, well below the app's 256 KiB row limit with the heights and envelope added. */
	static final int MAX_TILE_CHARS = 96 * 1024;
	public static final int SIZE = Constants.SCENE_SIZE;
	/** The client's colour for a face it does not draw. */
	public static final int HIDDEN = 12345678;

	/** Where a row read back goes, in world tiles on map planes. */
	public interface Sink
	{
		/** A paint {0, sw, se, ne, nw, texture} or a shaped tile {shape, rotation, then a, b, c, texture per face}; null for none. */
		void tile(int plane, int x, int y, int[] entry);

		void corner(int plane, int x, int y, int height);

		void bridge(int x, int y);
	}

	private GroundRows()
	{
	}

	public static List<JsonObject> of(WorldView view, String dimension)
	{
		return of(view, dimension, SIZE, SIZE);
	}

	/** The same rows for a scene of its own size: a Sailing boat's world view is smaller than the map's. */
	public static List<JsonObject> of(WorldView view, String dimension, int sizeX, int sizeY)
	{
		List<JsonObject> rows = new ArrayList<>();
		Scene scene = view.getScene();
		Tile[][][] tiles = scene == null ? null : scene.getTiles();
		if (tiles == null)
		{
			return rows;
		}
		int[][][] heights = view.getTileHeights();
		byte[][][] settings = view.getTileSettings();
		for (int plane = 0; plane < Constants.MAX_Z; plane++)
		{
			int start = 0, chars = 0;
			List<JsonArray> band = new ArrayList<>();
			for (int x = 0; x < sizeX; x++)
			{
				JsonArray column = new JsonArray();
				for (int y = 0; y < sizeY; y++)
				{
					tile(column, physical(tiles, settings, plane, x, y));
				}
				int length = column.toString().length() + 1;
				if (!band.isEmpty() && chars + length > MAX_TILE_CHARS)
				{
					rows.add(row(view, dimension, plane, start, band, heights, settings, sizeY));
					start = x;
					chars = 0;
					band = new ArrayList<>();
				}
				band.add(column);
				chars += length;
			}
			rows.add(row(view, dimension, plane, start, band, heights, settings, sizeY));
		}
		return rows;
	}

	/** The client moves a bridge's floors down one display plane; rows keep the map's own planes. */
	static boolean bridge(byte[][][] settings, int x, int y)
	{
		return settings != null && settings.length > 1 && settings[1] != null && x < settings[1].length
			&& settings[1][x] != null && y < settings[1][x].length && (settings[1][x][y] & 2) != 0;
	}

	private static Tile physical(Tile[][][] tiles, byte[][][] settings, int plane, int x, int y)
	{
		if (!bridge(settings, x, y))
		{
			return at(tiles, plane, x, y);
		}
		if (plane > 0)
		{
			return at(tiles, plane - 1, x, y);
		}
		Tile top = at(tiles, 0, x, y);
		return top == null ? null : top.getBridge();
	}

	private static Tile at(Tile[][][] tiles, int plane, int x, int y)
	{
		return plane < tiles.length && tiles[plane] != null && x < tiles[plane].length && tiles[plane][x] != null
			&& y < tiles[plane][x].length ? tiles[plane][x][y] : null;
	}

	private static void tile(JsonArray column, Tile tile)
	{
		SceneTilePaint paint = tile == null ? null : tile.getSceneTilePaint();
		if (paint != null)
		{
			JsonArray entry = new JsonArray();
			int sw = paint.getSwColor();
			entry.add(sw);
			entry.add(paint.getSeColor() - sw);
			entry.add(paint.getNeColor() - sw);
			entry.add(paint.getNwColor() - sw);
			if (paint.getTexture() >= 0) { entry.add(paint.getTexture()); }
			column.add(entry);
			return;
		}
		SceneTileModel model = tile == null ? null : tile.getSceneTileModel();
		int[] a = model == null ? null : model.getTriangleColorA(), b = model == null ? null : model.getTriangleColorB();
		int[] c = model == null ? null : model.getTriangleColorC();
		if (a == null || b == null || c == null)
		{
			column.add(0);
			return;
		}
		int[] textures = model.getTriangleTextureId();
		JsonArray entry = new JsonArray();
		entry.add(-model.getShape());
		entry.add(model.getRotation());
		for (int i = 0; i < Math.min(a.length, Math.min(b.length, c.length)); i++)
		{
			entry.add(a[i]);
			entry.add(b[i] - a[i]);
			entry.add(c[i] - a[i]);
			entry.add(textures != null && i < textures.length ? textures[i] : -1);
		}
		column.add(entry);
	}

	private static JsonObject row(WorldView view, String dimension, int plane, int start, List<JsonArray> band,
		int[][][] heights, byte[][][] settings, int sizeY)
	{
		JsonObject row = new JsonObject();
		row.addProperty("base_x", view.getBaseX());
		row.addProperty("base_y", view.getBaseY());
		row.addProperty("plane", plane);
		row.addProperty("x", start);
		row.addProperty("columns", band.size());
		JsonArray tiles = new JsonArray();
		for (JsonArray column : band) { tiles.add(column); }
		row.add("tiles", tiles);
		int[][] grid = heights != null && plane < heights.length ? heights[plane] : null;
		if (grid != null)
		{
			// Corner heights for x .. x + columns, 105 a column: the first, then each one's difference from the one south of it.
			JsonArray corners = new JsonArray();
			for (int x = start; x <= start + band.size() && x < grid.length; x++)
			{
				JsonArray column = new JsonArray();
				int[] values = grid[x];
				for (int y = 0; values != null && y <= sizeY && y < values.length; y++) { column.add(y == 0 ? values[0] : values[y] - values[y - 1]); }
				corners.add(column);
			}
			row.add("heights", corners);
		}
		if (plane == 1)
		{
			JsonArray bridges = new JsonArray();
			for (int x = start; x < start + band.size(); x++)
			{
				for (int y = 0; y < sizeY; y++)
				{
					if (bridge(settings, x, y)) { bridges.add(x); bridges.add(y); }
				}
			}
			row.add("bridges", bridges);
		}
		row.addProperty("dimension", dimension);
		return row;
	}

	/** Reads one row back, absolute values out, refusing anything the writer cannot produce. */
	public static void read(JsonObject row, Sink sink) throws IOException
	{
		int baseX = number(row, "base_x"), baseY = number(row, "base_y"), plane = number(row, "plane"), x0 = number(row, "x");
		JsonArray tiles = array(row, "tiles"), heights = array(row, "heights"), bridges = array(row, "bridges");
		if (baseX < 0 || baseY < 0 || baseX > 20_000 || baseY > 20_000 || plane < 0 || plane > 3 || x0 < 0 || x0 + tiles.size() > SIZE
			|| heights.size() > tiles.size() + 1 || bridges.size() % 2 != 0 || bridges.size() > 2 * SIZE * SIZE)
		{
			throw new IOException("Invalid ground row");
		}
		for (int c = 0; c < tiles.size(); c++)
		{
			JsonArray column = tiles.get(c).getAsJsonArray();
			if (column.size() != SIZE) { throw new IOException("Invalid ground column"); }
			for (int y = 0; y < SIZE; y++)
			{
				JsonElement e = column.get(y);
				if (!e.isJsonArray() && e.getAsInt() != 0) { throw new IOException("Invalid ground tile"); }
				sink.tile(plane, baseX + x0 + c, baseY + y, e.isJsonArray() ? entry(e.getAsJsonArray()) : null);
			}
		}
		for (int c = 0; c < heights.size(); c++)
		{
			JsonArray column = heights.get(c).getAsJsonArray();
			if (column.size() > SIZE + 1) { throw new IOException("Invalid ground heights"); }
			int height = 0;
			for (int y = 0; y < column.size(); y++)
			{
				height += value(column, y, 1 << 20);
				if (Math.abs(height) > 1 << 20) { throw new IOException("Invalid ground height"); }
				sink.corner(plane, baseX + x0 + c, baseY + y, height);
			}
		}
		for (int i = 0; i < bridges.size(); i += 2)
		{
			int x = value(bridges, i, SIZE), y = value(bridges, i + 1, SIZE);
			if (x < 0 || y < 0 || x >= SIZE || y >= SIZE) { throw new IOException("Invalid bridge tile"); }
			sink.bridge(baseX + x, baseY + y);
		}
	}

	private static int[] entry(JsonArray a) throws IOException
	{
		if (a.size() == 0) { throw new IOException("Invalid ground tile"); }
		if (a.get(0).getAsDouble() >= 0)
		{
			if (a.size() != 4 && a.size() != 5) { throw new IOException("Invalid ground paint"); }
			int sw = colour(a, 0);
			return new int[]{0, sw, sw + colour(a, 1), sw + colour(a, 2), sw + colour(a, 3), a.size() == 5 ? texture(a, 4) : -1};
		}
		int shape = -value(a, 0, 16), faces = (a.size() - 2) / 4, rotation = value(a, 1, 16);
		if (shape < 2 || shape > 12 || rotation < 0 || rotation > 3 || (a.size() - 2) % 4 != 0 || faces < 1 || faces > 6)
		{
			throw new IOException("Invalid shaped ground tile");
		}
		int[] entry = new int[a.size()];
		entry[0] = shape;
		entry[1] = rotation;
		for (int at = 2; at < a.size(); at += 4)
		{
			entry[at] = colour(a, at);
			entry[at + 1] = entry[at] + colour(a, at + 1);
			entry[at + 2] = entry[at] + colour(a, at + 2);
			entry[at + 3] = texture(a, at + 3);
		}
		return entry;
	}

	private static int colour(JsonArray a, int i) throws IOException
	{
		return value(a, i, 16_777_215);
	}

	private static int texture(JsonArray a, int i) throws IOException
	{
		int v = value(a, i, 65535);
		if (v < -1) { throw new IOException("Invalid ground texture"); }
		return v;
	}

	/** A whole number within plus or minus limit. */
	private static int value(JsonElement e, int limit) throws IOException
	{
		double v = e == null || e.isJsonNull() ? 0 : e.getAsDouble();
		if (v != Math.rint(v) || Math.abs(v) > limit) { throw new IOException("Invalid ground value"); }
		return (int) v;
	}

	private static int value(JsonArray a, int i, int limit) throws IOException
	{
		return value(a.get(i), limit);
	}

	private static int number(JsonObject o, String key) throws IOException
	{
		return value(o.get(key), 1 << 20);
	}

	private static JsonArray array(JsonObject o, String key)
	{
		return o.has(key) && o.get(key).isJsonArray() ? o.getAsJsonArray(key) : new JsonArray();
	}
}

package com.extrinsiccognition.embertide;

import java.util.Arrays;

/** A map with long keys that are not boxed, probed linearly; no removal. */
final class LongMap<V>
{
	private long[] keys = new long[64];
	private Object[] values = new Object[64];
	private boolean[] used = new boolean[64];
	private int size;

	int size()
	{
		return size;
	}

	boolean containsKey(long key)
	{
		return used[slot(key)];
	}

	@SuppressWarnings("unchecked")
	V get(long key)
	{
		int slot = slot(key);
		return used[slot] ? (V) values[slot] : null;
	}

	void put(long key, V value)
	{
		int slot = slot(key);
		if (!used[slot])
		{
			if ((size + 1) * 2 > keys.length)
			{
				grow();
				slot = slot(key);
			}
			used[slot] = true;
			keys[slot] = key;
			size++;
		}
		values[slot] = value;
	}

	void clear()
	{
		Arrays.fill(used, false);
		Arrays.fill(values, null);
		size = 0;
	}

	/** The key's slot, or the free slot where it would go. */
	private int slot(long key)
	{
		int mask = keys.length - 1;
		int slot = (int) ((key * 0x9E3779B97F4A7C15L) >>> 40) & mask;
		while (used[slot] && keys[slot] != key)
		{
			slot = (slot + 1) & mask;
		}
		return slot;
	}

	private void grow()
	{
		long[] oldKeys = keys;
		Object[] oldValues = values;
		boolean[] oldUsed = used;
		keys = new long[oldKeys.length * 2];
		values = new Object[oldKeys.length * 2];
		used = new boolean[oldKeys.length * 2];
		for (int i = 0; i < oldKeys.length; i++)
		{
			if (oldUsed[i])
			{
				int slot = slot(oldKeys[i]);
				used[slot] = true;
				keys[slot] = oldKeys[i];
				values[slot] = oldValues[i];
			}
		}
	}
}

package com.extrinsiccognition.embertide;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.io.BufferedOutputStream;
import java.io.ByteArrayOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Executor;
import java.util.function.Supplier;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;
import java.util.zip.ZipException;
import javax.swing.SwingUtilities;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.LinkBrowser;

public final class MccrFileRecorder implements Recorder
{
	/** Every Studio link the plugin opens; the tag names the plugin and nothing else. */
	public static final String STUDIO_URL = "https://embertide.gg/studio/?source=runelite";
	/** osrs.motion x and y as thousandths of a tile, each actor's first absolute and then its change. */
	public static final String MOTION_XY = "delta-milli";
	// The desktop's 128 MiB archive also includes ingest checkpoints and links.
	static final int MAX_BYTES = 120 * 1024 * 1024;
	static final int END_RESERVE = 16 * 1024;
	// The desktop importer accepts 120,000 records plus a header.
	static final int MAX_RECORDS = 120_000;
	// Rows reach the partial file about once a second, so a crash leaves a readable prefix.
	static final long FLUSH_NANOS = 1_000_000_000L;
	private final Gson gson;
	private final Filepath directory;
	private final Supplier<String> stem;
	private final Executor worker;
	private final int capacity;
	private final String unique = UUID.randomUUID().toString();
	// Rows not yet in the partial file: about a second's worth.
	private final List<byte[]> pending = new ArrayList<>();
	private int count;
	private Filepath sealed;
	private String name = "";
	private State state = State.IDLE;
	private String error = "";
	private int bytes;
	private boolean full;
	private CompletableFuture<Void> saving;
	private final Object io = new Object();
	private Filepath partial;
	private GZIPOutputStream out;
	private int written;
	private boolean finished;
	private boolean draining;
	private long drainedAt = System.nanoTime() - FLUSH_NANOS;
	private final Map<String, long[]> lastXY = new HashMap<>();
	/** The row being compacted's positions, kept only if the row is. */
	private final Map<String, long[]> moved = new HashMap<>();
	private boolean compact;
	private final RowWriter text = new RowWriter();

	public MccrFileRecorder(Gson gson, Filepath directory, Supplier<String> stem, Executor worker)
	{
		this(gson, directory, stem, worker, MAX_BYTES);
	}

	MccrFileRecorder(Gson gson, Filepath directory, Supplier<String> stem, Executor worker, int capacity)
	{
		this.gson = gson;
		this.directory = directory;
		this.stem = stem;
		this.worker = worker;
		this.capacity = capacity;
	}

	@Override
	public synchronized State state() { return state; }

	@Override
	public synchronized String error() { return error; }

	@Override
	public synchronized String captureId() { return name.isEmpty() ? unique : name; }

	public synchronized Filepath path() { return sealed; }

	@Override
	public synchronized String destination()
	{
		return sealed == null ? "" : "Will be saved as " + sealed;
	}

	@Override
	public synchronized boolean full() { return full; }

	@Override
	public synchronized CompletableFuture<Void> open(JsonObject header)
	{
		if (state != State.IDLE)
		{
			return CompletableFuture.failedFuture(new IllegalStateException("Recording already opened."));
		}
		// The supplier may read the local player's name: this stays on the client thread.
		name = stem.get() + "-" + unique;
		sealed = directory.joinSegment(name + ".embertide");
		state = State.READY;
		if (header.has("osrs") && header.get("osrs").isJsonObject())
		{
			header = header.deepCopy();
			header.getAsJsonObject("osrs").addProperty("motion_xy", MOTION_XY);
			compact = true;
		}
		if (!enqueue(header, false))
		{
			state = State.FAILED;
			error = "The recording header exceeds the size budget.";
			return CompletableFuture.failedFuture(new IOException(error));
		}
		return CompletableFuture.completedFuture(null);
	}

	@Override
	public synchronized boolean enqueue(JsonObject record, boolean control)
	{
		if (state != State.READY || (full && !control))
		{
			return false;
		}
		byte[] row = text.line(gson, record);
		// The budget counts rows as readers expand them, so the desktop's limit still holds.
		int plain = row.length;
		JsonObject compacted = compact ? compactMotion(record) : null;
		if (compacted != null)
		{
			row = text.line(gson, compacted);
		}
		if (bytes + plain > capacity - (control ? 0 : END_RESERVE)
			|| count >= MAX_RECORDS + (control ? 1 : 0))
		{
			full = true;
			return false;
		}
		pending.add(row);
		count++;
		bytes += plain;
		if (compacted != null)
		{
			lastXY.putAll(moved);
		}
		if (!draining && System.nanoTime() - drainedAt >= FLUSH_NANOS)
		{
			draining = true;
			drainedAt = System.nanoTime();
			try
			{
				worker.execute(this::drain);
			}
			catch (RuntimeException e)
			{
				draining = false;
			}
		}
		return true;
	}

	/** An osrs.motion row with x and y as thousandths, sharing the rest with the row; null for any other row. */
	private JsonObject compactMotion(JsonObject record)
	{
		JsonElement type = record.get("type");
		JsonElement payload = record.get("payload");
		if (type == null || !RowTypes.MOTION.equals(type.getAsString()) || payload == null || !payload.isJsonObject()
			|| !payload.getAsJsonObject().has("samples") || !payload.getAsJsonObject().get("samples").isJsonArray())
		{
			return null;
		}
		moved.clear();
		JsonArray samples = new JsonArray();
		for (JsonElement element : payload.getAsJsonObject().getAsJsonArray("samples"))
		{
			JsonArray sample = element.isJsonArray() ? element.getAsJsonArray() : null;
			if (sample == null || sample.size() < 3 || !isString(sample.get(0)) || !isNumber(sample.get(1)) || !isNumber(sample.get(2)))
			{
				samples.add(element);
				continue;
			}
			String id = sample.get(0).getAsString();
			long x = Math.round(sample.get(1).getAsDouble() * 1000.0);
			long y = Math.round(sample.get(2).getAsDouble() * 1000.0);
			long[] seen = moved.containsKey(id) ? moved.get(id) : lastXY.get(id);
			JsonArray compacted = new JsonArray(sample.size());
			for (int i = 0; i < sample.size(); i++)
			{
				compacted.add(i == 1 ? new JsonPrimitive(seen == null ? x : x - seen[0])
					: i == 2 ? new JsonPrimitive(seen == null ? y : y - seen[1]) : sample.get(i));
			}
			samples.add(compacted);
			moved.put(id, new long[]{x, y});
		}
		return replaced(record, "payload", replaced(payload.getAsJsonObject(), "samples", samples));
	}

	/** A shallow copy with one member replaced, members in the same order. */
	private static JsonObject replaced(JsonObject object, String key, JsonElement value)
	{
		JsonObject copy = new JsonObject();
		for (Map.Entry<String, JsonElement> member : object.entrySet())
		{
			copy.add(member.getKey(), key.equals(member.getKey()) ? value : member.getValue());
		}
		return copy;
	}

	private static boolean isString(JsonElement e) { return e.isJsonPrimitive() && e.getAsJsonPrimitive().isString(); }

	private static boolean isNumber(JsonElement e) { return e.isJsonPrimitive() && e.getAsJsonPrimitive().isNumber(); }

	private void drain()
	{
		try
		{
			synchronized (io)
			{
				if (state() == State.READY)
				{
					writePending();
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			// The next drain or the save rebuilds the partial file from its readable rows.
			closeStream();
		}
		finally
		{
			synchronized (this)
			{
				draining = false;
			}
		}
	}

	/** Appends the rows not yet on disk and sync-flushes them. Called holding io. */
	private void writePending() throws IOException
	{
		if (out == null)
		{
			Filepath broken = partial;
			int kept = written;
			openPartial();
			if (broken != null)
			{
				try
				{
					copyRows(broken);
				}
				catch (IOException | RuntimeException e)
				{
					closeStream();
					partial.deleteIfExists();
					partial = broken;
					written = kept;
					throw e;
				}
			}
		}
		List<byte[]> rows;
		synchronized (this)
		{
			rows = new ArrayList<>(pending);
		}
		for (byte[] row : rows)
		{
			out.write(row);
		}
		out.flush();
		written += rows.size();
		synchronized (this)
		{
			pending.subList(0, rows.size()).clear();
		}
	}

	private void openPartial() throws IOException
	{
		directory.createDirectories();
		Filepath fresh = directory.joinSegment(name + "-" + UUID.randomUUID() + ".embertide.partial");
		out = new GZIPOutputStream(new BufferedOutputStream(
			fresh.openOutputStream(StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE), 64 * 1024), 64 * 1024, true);
		partial = fresh;
	}

	/** Copies the rows already flushed to a broken partial file into the new one, then deletes it. */
	private void copyRows(Filepath broken) throws IOException
	{
		int want = written;
		written = 0;
		ByteArrayOutputStream line = new ByteArrayOutputStream();
		byte[] buffer = new byte[64 * 1024];
		try (InputStream in = new GZIPInputStream(broken.openInputStream(), 64 * 1024))
		{
			int read;
			while (written < want && (read = in.read(buffer)) > 0)
			{
				int from = 0;
				for (int i = 0; i < read && written < want; i++)
				{
					if (buffer[i] == '\n')
					{
						line.write(buffer, from, i + 1 - from);
						line.writeTo(out);
						line.reset();
						written++;
						from = i + 1;
					}
				}
				if (written < want)
				{
					line.write(buffer, from, read - from);
				}
			}
		}
		catch (EOFException | ZipException cutOff)
		{
			// Keep every whole row before the damage.
		}
		broken.deleteIfExists();
	}

	/** Test only: closes the stream as a failed write would. */
	void dropStream()
	{
		synchronized (io)
		{
			closeStream();
		}
	}

	private void closeStream()
	{
		if (out != null)
		{
			try { out.close(); }
			catch (IOException ignored) { }
			out = null;
		}
	}

	@Override
	public CompletableFuture<Void> flush() { return CompletableFuture.completedFuture(null); }

	@Override
	public synchronized CompletableFuture<Void> finish()
	{
		if (state == State.COMPLETE || state == State.IDLE)
		{
			return CompletableFuture.completedFuture(null);
		}
		if (state == State.FINISHING)
		{
			return saving;
		}
		state = State.FINISHING;
		error = "";
		saving = new CompletableFuture<>();
		try
		{
			worker.execute(this::write);
		}
		catch (RuntimeException e)
		{
			failed(e);
		}
		return saving;
	}

	private void write()
	{
		synchronized (io)
		{
			try
			{
				if (!finished)
				{
					writePending();
					// The gzip trailer: a finished part is a whole gzip file.
					out.finish();
					out.close();
					out = null;
					finished = true;
				}
				// No ATOMIC_MOVE: on some platforms it silently replaces the destination.
				partial.moveTo(sealed);
				partial = null;
				finished = false;
				written = 0;
				synchronized (this)
				{
					state = State.COMPLETE;
				}
				saving.complete(null);
			}
			catch (IOException | RuntimeException e)
			{
				closeStream();
				failed(e);
			}
		}
	}

	private synchronized void failed(Exception e)
	{
		state = State.FAILED;
		error = "Could not save the recording: " + e.getMessage();
		saving.completeExceptionally(e);
	}

	public void discard()
	{
		synchronized (io)
		{
			synchronized (this)
			{
				if (state != State.FAILED)
				{
					throw new IllegalStateException("Only a failed save can be discarded.");
				}
				pending.clear();
				state = State.COMPLETE;
			}
			closeStream();
			if (partial != null)
			{
				try { partial.deleteIfExists(); }
				catch (IOException | RuntimeException ignored) { }
				partial = null;
			}
			finished = false;
			written = 0;
		}
	}

	@Override
	public CompletableFuture<Void> openStudio()
	{
		if (state() != State.COMPLETE)
		{
			return CompletableFuture.failedFuture(new IOException("Save the recording before opening Studio."));
		}
		SwingUtilities.invokeLater(() -> LinkBrowser.browse(STUDIO_URL));
		return CompletableFuture.completedFuture(null);
	}
}

package com.extrinsiccognition.embertide;

import com.google.gson.JsonArray;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import java.util.function.LongSupplier;
import java.util.function.Supplier;

public final class MccrSession
{
	public static final String FORMAT = "mccr/0.1";
	public static final String PROFILE = "ec.mccr.spatial/1";
	public static final String SOURCE = "osrs.runelite";
	/** The plugin version, as build.gradle and runelite-plugin.properties give it. */
	public static final String VERSION = "0.5.0";
	public static final String RECORDER = "embertide-runelite/" + VERSION;
	public static final String GAME = "osrs";

	public final String id;
	public Instant capturedAt;
	/** Current coordinate space; the file header retains the initial dimension. */
	public String dimension;
	private long startedNanos;
	private final double maxSeconds;
	private int serial;
	private double lastRecordTime;
	private LongSupplier nanos = System::nanoTime;
	private Supplier<Instant> wall = Instant::now;
	// The rows of a tick share one time; its text is formatted once.
	private Instant tsBase;
	private double tsTime = -1;
	private String ts;
	private final Map<String, String> sessionIds = new HashMap<>();

	public MccrSession(String dimension, double maxSeconds)
	{
		this.id = "osrs-" + UUID.randomUUID();
		this.dimension = dimension;
		this.maxSeconds = maxSeconds;
		this.capturedAt = Instant.now();
		this.startedNanos = System.nanoTime();
	}

	/** Tests drive the clock. */
	void clock(LongSupplier nanos, Supplier<Instant> wall)
	{
		this.nanos = nanos;
		this.wall = wall;
	}

	public void rebase()
	{
		capturedAt = wall.get();
		startedNanos = nanos.getAsLong();
	}

	public double time()
	{
		double seconds = (nanos.getAsLong() - startedNanos) / 1_000_000_000.0;
		seconds = Math.max(0, Math.min(maxSeconds, seconds));
		return Math.round(seconds * 10000.0) / 10000.0;
	}

	public JsonObject record(String type, double t, JsonObject payload, String user)
	{
		// A row emitted after its callback sampled the time must not go back in time.
		t = Math.max(lastRecordTime, Math.max(0, Math.min(maxSeconds, t)));
		lastRecordTime = t;
		if (t != tsTime || capturedAt != tsBase)
		{
			ts = capturedAt.plusNanos((long) (t * 1_000_000_000L)).toString();
			tsTime = t;
			tsBase = capturedAt;
		}
		JsonObject row = new JsonObject();
		row.addProperty("id", id + ":r" + (++serial));
		row.addProperty("ts", ts);
		row.addProperty("elapsed_s", t);
		row.addProperty("source", SOURCE);
		row.addProperty("confidence", 1);
		row.addProperty("session_id", sessionIds.computeIfAbsent(user, who -> id + "/" + who));
		row.addProperty("user_id", user);
		row.add("character_id", JsonNull.INSTANCE);
		JsonObject salience = new JsonObject();
		salience.addProperty("rule_score", 0);
		salience.addProperty("first_time", false);
		salience.addProperty("danger", 0);
		row.add("salience_hints", salience);
		row.add("coverage", JsonNull.INSTANCE);
		row.addProperty("type", type);
		row.add("payload", payload);
		if (type.equals("world.event"))
		{
			row.add("caused_by", new JsonArray());
		}
		return row;
	}
}

