package com.extrinsiccognition.embertide.viewer;

/**
 * Object, NPC, item, body-kit, underlay and overlay definitions decoded from config bytes the running client hands over through
 * Client.getIndexConfig(). The API's compositions omit the model ids, recolours and transforms a model needs.
 * Opcodes follow RuneLite's cache loaders (BSD-2, notice above); an unknown opcode fails the
 * definition rather than misreading the rest.
 */
final class Definitions
{
	static final int UNDERLAY = 1, KIT = 3, OVERLAY = 4, OBJECT = 6, NPC = 9, ITEM = 10;

	private Definitions() { }

	static final class ObjectDef
	{
		int[] models, types;
		boolean impostors, rotated;
		short[] recolorFrom, recolorTo, retextureFrom, retextureTo;
		int fullRecolor = -1, sizeX = 1, sizeY = 1, animation = -1, ambient, contrast;
		int scaleX = 128, scaleHeight = 128, scaleY = 128, offsetX, offsetHeight, offsetY;
	}

	static final class NpcDef
	{
		int[] models;
		short[] recolorFrom, recolorTo, retextureFrom, retextureTo;
		int fullRecolor = -1, ambient, contrast, widthScale = 128, heightScale = 128;
	}

	static final class ItemDef
	{
		int maleModel0 = -1, maleModel1 = -1, maleModel2 = -1, femaleModel0 = -1, femaleModel1 = -1, femaleModel2 = -1;
		int maleOffset, femaleOffset, fullRecolor = -1;
		short[] recolorFrom, recolorTo, retextureFrom, retextureTo;
	}

	static final class KitDef
	{
		int[] models;
		short[] recolorFrom, recolorTo, retextureFrom, retextureTo;
	}

	/** A floor colour; hue is pre-multiplied by hueMultiplier, as the client sums it when blending neighbours. */
	static final class UnderlayDef
	{
		int rgb, hue, saturation, lightness, hueMultiplier;
	}

	/** A painted floor; texture -1 is a plain colour and rgb 0xFF00FF is a hidden one. The secondary colour is the minimap's. */
	static final class OverlayDef
	{
		static final int HIDDEN_RGB = 0xFF00FF;
		int rgb, texture = -1, secondaryRgb = -1, hue, saturation, lightness;
		boolean hideUnderlay = true;
		boolean hidden() { return texture < 0 && rgb == HIDDEN_RGB; }
	}

	static UnderlayDef underlay(byte[] bytes)
	{
		In in = new In(bytes); UnderlayDef d = new UnderlayDef();
		for (int op = in.u8(); op != 0; op = in.u8())
		{
			if (op == 1) { d.rgb = in.u24(); }
			else { throw new IllegalArgumentException("Unknown underlay opcode " + op); }
		}
		double[] hsl = hsl(d.rgb); double l = hsl[2], s = hsl[1];
		d.saturation = clamp((int) (s * 256)); d.lightness = clamp((int) (l * 256));
		d.hueMultiplier = Math.max(1, (int) ((l > .5 ? 1 - l : l) * s * 512));
		d.hue = (int) (d.hueMultiplier * hsl[0]);
		return d;
	}

	static OverlayDef overlay(byte[] bytes)
	{
		In in = new In(bytes); OverlayDef d = new OverlayDef();
		for (int op = in.u8(); op != 0; op = in.u8())
		{
			if (op == 1) { d.rgb = in.u24(); }
			else if (op == 2) { d.texture = in.u8(); }
			else if (op == 5) { d.hideUnderlay = false; }
			else if (op == 7) { d.secondaryRgb = in.u24(); }
			else { throw new IllegalArgumentException("Unknown overlay opcode " + op); }
		}
		double[] hsl = hsl(d.rgb);
		d.hue = (int) (256 * hsl[0]); d.saturation = clamp((int) (hsl[1] * 256)); d.lightness = clamp((int) (hsl[2] * 256));
		return d;
	}

	/** The client's RGB to hue (sixths of a turn over six, may be negative), saturation and lightness, all from 0..1 channels of /256. */
	private static double[] hsl(int rgb)
	{
		double r = (rgb >> 16 & 255) / 256.0, g = (rgb >> 8 & 255) / 256.0, b = (rgb & 255) / 256.0;
		double min = Math.min(r, Math.min(g, b)), max = Math.max(r, Math.max(g, b));
		double h = 0, s = 0, l = (min + max) / 2;
		if (min != max)
		{
			if (l < .5) { s = (max - min) / (max + min); }
			if (l >= .5) { s = (max - min) / (2 - max - min); }
			if (r == max) { h = (g - b) / (max - min); }
			else if (g == max) { h = 2 + (b - r) / (max - min); }
			else if (b == max) { h = 4 + (r - g) / (max - min); }
		}
		return new double[]{h / 6, s, l};
	}
	private static int clamp(int v) { return Math.max(0, Math.min(255, v)); }

	static ObjectDef object(byte[] bytes)
	{
		In in = new In(bytes); ObjectDef d = new ObjectDef();
		for (int op = in.u8(); op != 0; op = in.u8())
		{
			if (op == 1 || op == 6)
			{
				int n = in.u8();
				if (n > 0) { d.models = new int[n]; d.types = new int[n]; for (int i = 0; i < n; i++) { d.models[i] = op == 1 ? in.u16() : in.i32(); d.types[i] = in.u8(); } }
			}
			else if (op == 5 || op == 7)
			{
				int n = in.u8();
				if (n > 0) { d.types = null; d.models = new int[n]; for (int i = 0; i < n; i++) { d.models[i] = op == 5 ? in.u16() : in.i32(); } }
			}
			else if (op == 2) { in.string(); }
			else if (op == 14) { d.sizeX = in.u8(); }
			else if (op == 15) { d.sizeY = in.u8(); }
			else if (op == 17 || op == 18 || op == 21 || op == 22 || op == 23 || op == 27 || op == 64 || op == 73 || op == 74
				|| op == 89 || op == 90 || op == 94) { continue; }
			else if (op == 19 || op == 28 || op == 69 || op == 75 || op == 81 || op == 91 || op == 95 || op == 96) { in.u8(); }
			else if (op == 24) { d.animation = in.u16(); if (d.animation == 0xffff) { d.animation = -1; } }
			else if (op == 29) { d.ambient = in.i8(); }
			else if (op >= 30 && op < 35) { in.string(); }
			else if (op == 39) { d.contrast = in.i8() * 25; }
			else if (op == 40) { short[][] pairs = pairs(in); d.recolorFrom = pairs[0]; d.recolorTo = pairs[1]; }
			else if (op == 41) { short[][] pairs = pairs(in); d.retextureFrom = pairs[0]; d.retextureTo = pairs[1]; }
			else if (op == 42) { d.fullRecolor = (short) in.u16(); }
			else if (op == 61 || op == 68 || op == 82) { in.u16(); }
			else if (op == 62) { d.rotated = true; }
			else if (op == 65) { d.scaleX = in.u16(); }
			else if (op == 66) { d.scaleHeight = in.u16(); }
			else if (op == 67) { d.scaleY = in.u16(); }
			else if (op == 70) { d.offsetX = in.u16(); }
			else if (op == 71) { d.offsetHeight = in.u16(); }
			else if (op == 72) { d.offsetY = in.u16(); }
			else if (op == 77 || op == 92)
			{
				in.u16(); in.u16(); if (op == 92) { in.u16(); }
				int n = in.u8(); for (int i = 0; i <= n; i++) { in.u16(); }
				d.impostors = true;
			}
			else if (op == 78) { in.u16(); in.u8(); in.u8(); }
			else if (op == 79) { in.u16(); in.u16(); in.u8(); in.u8(); int n = in.u8(); for (int i = 0; i < n; i++) { in.u16(); } }
			else if (op == 93) { in.u8(); in.u16(); in.u8(); in.u16(); }
			else if (op == 100) { in.u8(); in.u8(); in.string(); }
			else if (op == 101) { in.u8(); in.u16(); in.u16(); in.i32(); in.i32(); in.string(); }
			else if (op == 102) { in.u8(); in.u16(); in.u16(); in.u16(); in.i32(); in.i32(); in.string(); }
			else if (op == 249) { in.params(); }
			else { throw new IllegalArgumentException("Unknown object opcode " + op); }
		}
		return d;
	}

	static NpcDef npc(byte[] bytes)
	{
		In in = new In(bytes); NpcDef d = new NpcDef();
		for (int op = in.u8(); op != 0; op = in.u8())
		{
			if (op == 1 || op == 61) { int n = in.u8(); d.models = new int[n]; for (int i = 0; i < n; i++) { d.models[i] = op == 1 ? in.u16() : in.i32(); } }
			else if (op == 60 || op == 62) { int n = in.u8(); for (int i = 0; i < n; i++) { if (op == 60) { in.u16(); } else { in.i32(); } } }
			else if (op == 2) { in.string(); }
			else if (op == 12) { in.u8(); }
			else if (op == 13 || op == 14 || op == 15 || op == 16 || op == 18 || (op >= 74 && op <= 79) || op == 95 || op == 103
				|| op == 114 || op == 116 || op == 124 || op == 126 || op == 146) { in.u16(); }
			else if (op == 17 || op == 115 || op == 117) { in.u16(); in.u16(); in.u16(); in.u16(); }
			else if (op >= 30 && op < 35) { in.string(); }
			else if (op == 40) { short[][] pairs = pairs(in); d.recolorFrom = pairs[0]; d.recolorTo = pairs[1]; }
			else if (op == 41) { short[][] pairs = pairs(in); d.retextureFrom = pairs[0]; d.retextureTo = pairs[1]; }
			else if (op == 42) { d.fullRecolor = (short) in.u16(); }
			else if (op == 93 || op == 99 || op == 107 || op == 109 || op == 111 || op == 122 || op == 123 || op == 129 || op == 130
				|| op == 145 || op == 147) { continue; }
			else if (op == 97) { d.widthScale = in.u16(); }
			else if (op == 98) { d.heightScale = in.u16(); }
			else if (op == 100) { d.ambient = in.i8(); }
			else if (op == 101) { d.contrast = in.i8(); }
			else if (op == 102)
			{
				int bits = in.u8();
				for (int i = 0; bits >> i != 0; i++) { if ((bits & 1 << i) != 0) { in.bigSmart2(); in.u16SmartMinusOne(); } }
			}
			else if (op == 106 || op == 118)
			{
				in.u16(); in.u16(); if (op == 118) { in.u16(); }
				int n = in.u8(); for (int i = 0; i <= n; i++) { in.u16(); }
			}
			else if (op == 249) { in.params(); }
			else if (op == 251) { in.u8(); in.u8(); in.string(); }
			else if (op == 252) { in.u8(); in.u16(); in.u16(); in.i32(); in.i32(); in.string(); }
			else if (op == 253) { in.u8(); in.u16(); in.u16(); in.u16(); in.i32(); in.i32(); in.string(); }
			else { throw new IllegalArgumentException("Unknown NPC opcode " + op); }
		}
		return d;
	}

	static ItemDef item(byte[] bytes)
	{
		In in = new In(bytes); ItemDef d = new ItemDef();
		for (int op = in.u8(); op != 0; op = in.u8())
		{
			if (op == 1 || op == 4 || op == 5 || op == 6 || op == 7 || op == 8 || op == 90 || op == 91 || op == 92 || op == 93
				|| op == 94 || op == 95 || op == 97 || op == 98 || (op >= 110 && op <= 112) || op == 139 || op == 140 || op == 148 || op == 149
				|| op == 75) { in.u16(); }
			else if (op == 2 || op == 3 || op == 9 || (op >= 30 && op < 40)) { in.string(); }
			else if (op == 11 || op == 15 || op == 16 || op == 65 || op == 160 || op == 251) { continue; }
			else if (op == 12 || op == 44 || (op >= 51 && op <= 54)) { in.i32(); }
			else if (op == 13 || op == 14 || op == 27 || op == 42 || op == 113 || op == 114 || op == 115) { in.u8(); }
			else if (op == 23) { d.maleModel0 = in.u16(); d.maleOffset = in.u8(); }
			else if (op == 24) { d.maleModel1 = in.u16(); }
			else if (op == 25) { d.femaleModel0 = in.u16(); d.femaleOffset = in.u8(); }
			else if (op == 26) { d.femaleModel1 = in.u16(); }
			else if (op == 45) { d.maleModel0 = in.i32(); d.maleOffset = in.u8(); }
			else if (op == 46) { d.maleModel1 = in.i32(); }
			else if (op == 47) { d.maleModel2 = in.i32(); }
			else if (op == 48) { d.femaleModel0 = in.i32(); d.femaleOffset = in.u8(); }
			else if (op == 49) { d.femaleModel1 = in.i32(); }
			else if (op == 50) { d.femaleModel2 = in.i32(); }
			else if (op == 78) { d.maleModel2 = in.u16(); }
			else if (op == 79) { d.femaleModel2 = in.u16(); }
			else if (op == 40) { short[][] pairs = pairs(in); d.recolorFrom = pairs[0]; d.recolorTo = pairs[1]; }
			else if (op == 41) { short[][] pairs = pairs(in); d.retextureFrom = pairs[0]; d.retextureTo = pairs[1]; }
			else if (op == 43) { in.u8(); while (in.u8() != 0) { in.string(); } }
			else if (op == 99) { d.fullRecolor = (short) in.u16(); }
			else if (op >= 100 && op < 110) { in.u16(); in.u16(); }
			else if (op == 161) { int n = in.u16(); for (int i = 0; i < n; i++) { in.u16(); } }
			else if (op == 200) { in.u8(); in.u8(); in.string(); }
			else if (op == 201) { in.u8(); in.u16(); in.u16(); in.i32(); in.i32(); in.string(); }
			else if (op == 202) { in.u8(); in.u16(); in.u16(); in.u16(); in.i32(); in.i32(); in.string(); }
			else if (op == 249) { in.params(); }
			else { throw new IllegalArgumentException("Unknown item opcode " + op); }
		}
		return d;
	}

	static KitDef kit(byte[] bytes)
	{
		In in = new In(bytes); KitDef d = new KitDef();
		for (int op = in.u8(); op != 0; op = in.u8())
		{
			if (op == 1) { in.u8(); }
			else if (op == 2 || op == 5) { int n = in.u8(); d.models = new int[n]; for (int i = 0; i < n; i++) { d.models[i] = op == 2 ? in.u16() : in.i32(); } }
			else if (op == 3) { continue; }
			else if (op == 40) { short[][] pairs = pairs(in); d.recolorFrom = pairs[0]; d.recolorTo = pairs[1]; }
			else if (op == 41) { short[][] pairs = pairs(in); d.retextureFrom = pairs[0]; d.retextureTo = pairs[1]; }
			else if (op >= 60 && op < 70) { in.u16(); }
			else if (op >= 70 && op < 80) { in.i32(); }
			else { throw new IllegalArgumentException("Unknown kit opcode " + op); }
		}
		return d;
	}

	private static short[][] pairs(In in)
	{
		int n = in.u8(); short[] from = new short[n], to = new short[n];
		for (int i = 0; i < n; i++) { from[i] = (short) in.u16(); to[i] = (short) in.u16(); }
		return new short[][]{from, to};
	}

	/** Big-endian config bytes; reading past the end throws, so a truncated definition is never half-used. */
	private static final class In
	{
		private final byte[] b; private int i;
		In(byte[] b) { this.b = b; }
		int u8() { if (i >= b.length) { throw new IllegalArgumentException("Truncated definition"); } return b[i++] & 255; }
		int i8() { return (byte) u8(); }
		int u16() { return u8() << 8 | u8(); }
		int u24() { return u8() << 16 | u16(); }
		int i32() { return u16() << 16 | u16(); }
		void string() { int start = i; while (u8() != 0) { if (i - start > 4096) { throw new IllegalArgumentException("Overlong string"); } } }
		void bigSmart2() { if (i < b.length && b[i] < 0) { i32(); } else { u16(); } }
		void u16SmartMinusOne() { if (u8() >= 128) { u8(); } }
		void params()
		{
			int n = u8();
			for (int k = 0; k < n; k++)
			{
				int type = u8(); u8(); u16();
				if (type == 1) { string(); } else if (type == 2) { i32(); i32(); } else { i32(); }
			}
		}
	}
}

package com.extrinsiccognition.embertide.viewer;

import net.runelite.api.GameObject;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.ObjectID;

/** Uses the house's exit portal, not coordinates which other instances can reuse. */
final class HouseGate
{
	static boolean containsHouse(WorldView view)
	{
		if (view == null || !view.isInstance() || view.getScene() == null)
		{
			return false;
		}
		Tile[][][] planes = view.getScene().getTiles();
		if (planes == null)
		{
			return false;
		}
		for (Tile[][] plane : planes)
		{
			if (plane == null)
			{
				continue;
			}
			for (Tile[] column : plane)
			{
				if (column == null)
				{
					continue;
				}
				for (Tile tile : column)
				{
					if (tile == null || tile.getGameObjects() == null)
					{
						continue;
					}
					for (GameObject object : tile.getGameObjects())
					{
						if (object != null && object.getId() == ObjectID.POH_EXIT_PORTAL)
						{
							return true;
						}
					}
				}
			}
		}
		return false;
	}
}

package com.extrinsiccognition.embertide.viewer;

import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.GraphicsObject;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Projectile;
import net.runelite.api.Renderable;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.hooks.DrawCallbacks;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;

/**
 * Hides scene submissions, leaving the house and its collision data intact. Works with any renderer that rebuilds
 * zones on invalidateZone and asks RenderCallbackManager about each tile: RuneLite's GPU plugin and 117 HD's default
 * renderer do. Whether this one does is confirmed by it asking about the hidden house, not by its class.
 */
final class HouseIsolation implements RenderCallback, AutoCloseable
{
	static final String NEEDS_GPU = "Hide surroundings needs a GPU renderer. Turn on RuneLite's GPU plugin or 117 HD, or untick Hide surroundings.";
	static final String DID_NOT_HIDE = "Your renderer does not hide the house. Hide surroundings works with RuneLite's GPU plugin and 117 HD, "
		+ "but not 117 HD's legacy renderer. Untick Hide surroundings to place the replay with your house showing.";
	/** Drawn frames to wait for the renderer to rebuild the house before concluding it never asks. */
	static final int CONFIRM_FRAMES = 30;
	private final Client client;
	private final RenderCallbackManager callbacks;
	// GPU uploads can run on the map-loader thread. Publish the scene identity,
	// not a flag that might accidentally hide an incoming non-house scene.
	private volatile Scene hiddenScene;
	private volatile Player localPlayer;
	private volatile boolean confirmed;
	private DrawCallbacks renderer, failedRenderer;
	private int frames;

	HouseIsolation(Client client, RenderCallbackManager callbacks)
	{
		this.client = client;
		this.callbacks = callbacks;
	}

	/** Why hiding cannot work with the current renderer, or null when it can be tried. */
	String problem()
	{
		DrawCallbacks current = client.getDrawCallbacks();
		return current == null ? NEEDS_GPU : current == failedRenderer ? DID_NOT_HIDE : null;
	}

	boolean supported() { return problem() == null; }
	boolean active() { return hiddenScene != null; }
	boolean matches(Scene scene) { return hiddenScene == scene; }
	boolean confirmed() { return confirmed; }
	/** The renderer hidden with is no longer the client's. */
	boolean rendererChanged() { return hiddenScene != null && client.getDrawCallbacks() != renderer; }

	/** Count a drawn frame; true once the renderer has had CONFIRM_FRAMES to ask about the house and has not. */
	boolean frame()
	{
		if (hiddenScene == null || confirmed || ++frames < CONFIRM_FRAMES)
		{
			return false;
		}
		failedRenderer = renderer;
		return true;
	}

	void hide(Scene scene)
	{
		String problem = problem();
		if (problem != null)
		{
			throw new IllegalStateException(problem);
		}
		if (scene == null)
		{
			throw new IllegalArgumentException("No house scene is loaded.");
		}
		if (hiddenScene == scene)
		{
			return;
		}
		close();
		renderer = client.getDrawCallbacks();
		confirmed = false;
		frames = 0;
		localPlayer = client.getLocalPlayer();
		hiddenScene = scene;
		callbacks.register(this);
		try
		{
			invalidate(scene, renderer);
		}
		catch (RuntimeException e)
		{
			hiddenScene = null;
			localPlayer = null;
			renderer = null;
			callbacks.unregister(this);
			throw e;
		}
	}

	@Override public boolean drawTile(Scene scene, Tile tile)
	{
		if (scene != hiddenScene)
		{
			return true;
		}
		confirmed = true;
		return false;
	}

	@Override public boolean drawObject(Scene scene, TileObject object)
	{
		if (scene != hiddenScene)
		{
			return true;
		}
		confirmed = true;
		if (!(object instanceof GameObject))
		{
			return false;
		}
		// TileObject's documented hash layout puts entity type in bits 16..18.
		// Static house objects are type 2. RuneLite projections are temporary
		// objects; their zero/-1 tags are not map objects. Keep their draw path.
		int type = (int) (object.getHash() >>> 16 & 7);
		if (type >= 1 && type <= 4)
		{
			return false;
		}
		return keepEntity(((GameObject) object).getRenderable());
	}

	@Override public boolean addEntity(Renderable entity, boolean ui)
	{
		return hiddenScene == null || keepEntity(entity);
	}

	private boolean keepEntity(Renderable entity)
	{
		if (entity instanceof Player)
		{
			return entity == localPlayer;
		}
		// Replay controllers use their own renderable, not live Actor objects.
		return !(entity instanceof NPC || entity instanceof Projectile || entity instanceof GraphicsObject || entity instanceof Scene);
	}

	@Override public void close()
	{
		Scene previous = hiddenScene;
		DrawCallbacks previousRenderer = renderer;
		if (previous == null)
		{
			return;
		}
		hiddenScene = null;
		localPlayer = null;
		renderer = null;
		callbacks.unregister(this);
		WorldView view = client.getTopLevelWorldView();
		// A scene reload already rebuilds the incoming scene, and a new renderer
		// uploads its own. Never invalidate a discarded scene or another renderer.
		if (view != null && view.getScene() == previous && client.getGameState() == GameState.LOGGED_IN
			&& previousRenderer != null && client.getDrawCallbacks() == previousRenderer)
		{
			invalidate(previous, previousRenderer);
		}
	}

	private static void invalidate(Scene scene, DrawCallbacks renderer)
	{
		// Zone renderers cache static geometry by 8x8 extended-scene zone. Changing
		// a callback alone cannot hide an already uploaded floor or restore it.
		Tile[][][] tiles = scene.getExtendedTiles();
		if (tiles == null)
		{
			return;
		}
		int zones = Constants.EXTENDED_SCENE_SIZE >> 3;
		boolean[][] touched = new boolean[zones][zones];
		for (Tile[][] plane : tiles)
		{
			if (plane == null)
			{
				continue;
			}
			for (int x = 0; x < Math.min(plane.length, zones * 8); x++)
			{
				Tile[] column = plane[x];
				if (column == null)
				{
					continue;
				}
				for (int y = 0; y < Math.min(column.length, zones * 8); y++)
				{
					if (column[y] != null && !touched[x >> 3][y >> 3])
					{
						touched[x >> 3][y >> 3] = true;
						renderer.invalidateZone(scene, x >> 3, y >> 3);
					}
				}
			}
		}
	}
}

package com.extrinsiccognition.embertide.viewer;

/** One rigid transform, shared by terrain, scenery and every animated actor. */
final class Placement
{
	final double sourceX, sourceY, sourceHeight, scale;
	final int anchorX, anchorY, anchorZ, plane, worldView, quarterTurns;

	Placement(double sourceX, double sourceY, double sourceHeight, double scale,
		int anchorX, int anchorY, int anchorZ, int plane, int worldView, int quarterTurns)
	{
		this.sourceX = sourceX;
		this.sourceY = sourceY;
		this.sourceHeight = sourceHeight;
		this.scale = scale;
		this.anchorX = anchorX;
		this.anchorY = anchorY;
		this.anchorZ = anchorZ;
		this.plane = plane;
		this.worldView = worldView;
		this.quarterTurns = Math.floorMod(quarterTurns, 4);
	}

	int x(double x, double y) { return anchorX + (int) Math.round(rotateX(x - sourceX, y - sourceY) * 128 * scale); }
	int y(double x, double y) { return anchorY + (int) Math.round(rotateY(x - sourceX, y - sourceY) * 128 * scale); }
	int z(double height) { return anchorZ - (int) Math.round((height - sourceHeight) * scale); }
	int orientation(int orientation) { return (orientation + quarterTurns * 512) & 2047; }

	private double rotateX(double x, double y)
	{
		switch (quarterTurns) { case 1: return y; case 2: return -x; case 3: return -y; default: return x; }
	}

	private double rotateY(double x, double y)
	{
		switch (quarterTurns) { case 1: return -x; case 2: return -y; case 3: return x; default: return y; }
	}
}

package com.extrinsiccognition.embertide.viewer;

/** Client-thread clock. Time advances with elapsed wall time, independent of game ticks. */
final class PlaybackClock
{
	private double time;
	private double duration;
	private double speed = 1;
	private boolean playing;
	private boolean loop = true;
	private long lastNanos;

	void load(double length, long now)
	{
		duration = Math.max(0, length);
		time = 0;
		playing = false;
		lastNanos = now;
	}

	void tick(long now)
	{
		double elapsed = Math.max(0, (now - lastNanos) / 1e9);
		lastNanos = now;
		if (!playing || duration == 0)
		{
			return;
		}
		time += elapsed * speed;
		if (time >= duration)
		{
			if (loop)
			{
				time %= duration;
			}
			else
			{
				time = duration;
				playing = false;
			}
		}
	}

	void seek(double value, long now)
	{
		time = Math.max(0, Math.min(duration, value));
		lastNanos = now;
	}

	void play(boolean value, long now)
	{
		tick(now);
		if (value && time >= duration)
		{
			time = 0;
		}
		playing = value;
	}

	void speed(double value, long now)
	{
		tick(now);
		speed = Math.max(.1, Math.min(4, value));
	}

	void loop(boolean value) { loop = value; }
	double time() { return time; }
	double duration() { return duration; }
	boolean playing() { return playing; }
}

package com.extrinsiccognition.embertide.viewer;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Compact replay data; no RuneLite objects and no retained JSON trees. */
final class Recording
{
	int revision;
	double duration;
	int rows;
	final List<Scene> scenes = new ArrayList<>();
	final Map<String, List<Appearance>> appearances = new LinkedHashMap<>();

	Scene sceneAt(double time)
	{
		Scene result = scenes.get(0);
		for (Scene scene : scenes) { if (scene.start > time) { break; } result = scene; }
		return result;
	}

	Appearance appearance(String id, double time) { return at(appearances.get(id), time); }

	interface Timed { double time(); }

	static <T extends Timed> int floor(List<T> list, double time)
	{
		if (list == null)
		{
			return -1;
		}
		int lo = 0, hi = list.size() - 1, found = -1;
		while (lo <= hi)
		{
			int mid = (lo + hi) >>> 1;
			if (list.get(mid).time() <= time)
			{
				found = mid;
				lo = mid + 1;
			}
			else
			{
				hi = mid - 1;
			}
		}
		return found;
	}

	static <T extends Timed> T at(List<T> list, double time)
	{
		int i = floor(list, time); return i < 0 ? null : list.get(i);
	}

	static final class Scene
	{
		final double start;
		final String dimension;
		final Map<String, Actor> actors = new LinkedHashMap<>();
		final Map<String, Ground> ground = new LinkedHashMap<>();
		final Map<String, List<Scenery>> objects = new LinkedHashMap<>();
		final Terrain terrain = new Terrain();
		int objectEntries;
		Scene(double start, String dimension)
		{
			this.start = start;
			this.dimension = dimension;
			terrain.instance = dimension.startsWith("osrs:instance");
		}

		double height(double x, double y, int plane)
		{
			double h = terrain.surface(x, y, plane);
			if (Double.isFinite(h))
			{
				return h;
			}
			Ground g = ground.get(groundKey((int) Math.floor(x), (int) Math.floor(y), plane));
			return g == null ? 0 : g.height;
		}

		Sample origin(double time)
		{
			Actor player = actors.get("player");
			if (player != null)
			{
				Sample sample = player.sample(time);
				if (sample != null)
				{
					return sample;
				}
				if (!player.motion.isEmpty())
				{
					return player.motion.get(0);
				}
				if (!player.poses.isEmpty())
				{
					return player.poses.get(0);
				}
			}
			for (Actor actor : actors.values())
			{
				Sample sample = actor.sample(time);
				if (sample != null)
				{
					return sample;
				}
			}
			return null;
		}
	}

	static String groundKey(int x, int y, int plane) { return x + ":" + y + ":" + plane; }

	static final class Ground
	{
		final int x, y, plane;
		final double height;
		final String material;
		Ground(int x, int y, int plane, double height, String material)
		{
			this.x = x;
			this.y = y;
			this.plane = plane;
			this.height = height;
			this.material = material;
		}
	}

	static final class Actor
	{
		final String id;
		int npcId = -1;
		final List<Sample> poses = new ArrayList<>();
		final List<Sample> motion = new ArrayList<>();
		final List<Presence> presence = new ArrayList<>();
		Sample lastAnimationSample;
		Actor(String id) { this.id = id; }

		Sample sample(double time)
		{
			Sample coarse = at(poses, time);
			Presence state = at(presence, time);
			if (state != null && !state.present)
			{
				return null;
			}
			if (coarse == null || time - coarse.t > 2)
			{
				return null;
			}
			int index = floor(motion, time);
			Sample fine = index < 0 ? null : motion.get(index);
			// A rejoin/plane change invalidates a previously held motion position.
			if (fine == null || fine.plane != coarse.plane || (state != null && fine.t < state.t))
			{
				return interpolate(poses, floor(poses, time), time);
			}
			Sample result = interpolate(motion, index, time);
			result.npcId = coarse.npcId;
			return result;
		}

		private Sample interpolate(List<Sample> list, int index, double time)
		{
			if (index < 0)
			{
				return null;
			}
			Sample a = list.get(index), out = a.copy();
			if (index + 1 < list.size())
			{
				Sample b = list.get(index + 1);
				double gap = b.t - a.t;
				int boundary = floor(presence, a.t) + 1;
				boolean continuous = boundary >= presence.size() || presence.get(boundary).t > b.t;
				if (continuous && gap > 0 && gap <= 1.2 && a.plane == b.plane && Math.hypot(b.x - a.x, b.y - a.y) <= 8)
				{
					double f = Math.max(0, Math.min(1, (time - a.t) / gap));
					out.x += (b.x - a.x) * f;
					out.y += (b.y - a.y) * f;
					int turn = ((b.orientation - a.orientation + 1024) & 2047) - 1024;
					out.orientation = (a.orientation + (int) Math.round(turn * f)) & 2047;
				}
			}
			return out;
		}
	}

	static final class Sample implements Timed
	{
		final double t;
		double poseStart, frameStart;
		double x, y;
		final int plane, animation, frame, pose;
		int orientation, npcId;
		Sample(double t, double x, double y, int plane, int orientation, int animation, int frame, int pose, int npcId)
		{
			this.t = t;
			this.poseStart = this.frameStart = t;
			this.x = x;
			this.y = y;
			this.plane = plane;
			this.orientation = orientation;
			this.animation = animation;
			this.frame = frame;
			this.pose = pose;
			this.npcId = npcId;
		}

		public double time() { return t; }

		Sample copy()
		{
			Sample copy = new Sample(t, x, y, plane, orientation, animation, frame, pose, npcId);
			copy.poseStart = poseStart;
			copy.frameStart = frameStart;
			return copy;
		}
	}

	static final class Presence implements Timed
	{
		final double t;
		final boolean present;

		Presence(double t, boolean present)
		{
			this.t = t;
			this.present = present;
		}

		public double time() { return t; }
	}

	static final class Appearance implements Timed
	{
		final double t;
		final int[] equipment, colors;
		final boolean female;
		final int npcId;

		Appearance(double t, int[] equipment, int[] colors, boolean female, int npcId)
		{
			this.t = t;
			this.equipment = equipment;
			this.colors = colors;
			this.female = female;
			this.npcId = npcId;
		}

		public double time() { return t; }
	}

	static final class Scenery implements Timed
	{
		final double t;
		double animationStart;
		final int x, y, plane, id, type, orientation, kind;
		final boolean present;
		Scenery(double t, int x, int y, int plane, int id, int type, int orientation, int kind, boolean present)
		{
			this.t = t;
			this.animationStart = t;
			this.x = x;
			this.y = y;
			this.plane = plane;
			this.id = id;
			this.type = type;
			this.orientation = orientation;
			this.kind = kind;
			this.present = present;
		}

		public double time() { return t; }
		String key() { return key(id); }
		String key(int originalId) { return groundKey(x, y, plane) + ":" + kind + ":" + originalId + ":" + type + ":" + orientation; }
	}
}

package com.extrinsiccognition.embertide.viewer;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.extrinsiccognition.embertide.GroundRows;
import com.extrinsiccognition.embertide.MccrFileRecorder;
import com.extrinsiccognition.embertide.MccrSession;
import com.extrinsiccognition.embertide.RowTypes;
import com.extrinsiccognition.embertide.SceneMapper;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.FilterInputStream;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PushbackInputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.HashMap;
import java.util.Map;
import java.util.zip.GZIPInputStream;
import net.runelite.client.util.Filepath;
import static com.extrinsiccognition.embertide.viewer.Recording.*;

final class RecordingReader
{
	static final long MAX_BYTES = 128L * 1024 * 1024;
	static final int MAX_LINE = 2 * 1024 * 1024;
	static final long MAX_GROUND_VALUES = 40_000_000;
	static final int MAX_SCENE_OBJECTS = 100_000, MAX_OBJECTS = 2_000_000;
	private static final String LEGACY_GROUND = "osrs:ground";
	private int samples, cells, objects, actors, appearances, terrainValues;
	private long groundValues;
	private boolean deltaMotion;
	private final Map<String, long[]> motionCoordinates = new HashMap<>();

	/** A file in the plugin's own folder; Filepath cannot name one outside it. */
	Recording read(Filepath file) throws IOException
	{
		if (!file.isFile() || file.size() > MAX_BYTES)
		{
			throw new IOException("Choose a recording file smaller than 128 MiB.");
		}
		return read(file.openInputStream());
	}

	Recording read(InputStream source) throws IOException
	{
		samples = cells = objects = actors = appearances = terrainValues = 0;
		groundValues = 0;
		motionCoordinates.clear();
		deltaMotion = false;
		Recording recording = new Recording();
		try (PushbackInputStream peek = new PushbackInputStream(source, 2))
		{
			int first = peek.read(), second = peek.read();
			if (second >= 0)
			{
				peek.unread(second);
			}
			if (first >= 0)
			{
				peek.unread(first);
			}
			InputStream decoded = first == 31 && second == 139 ? new GZIPInputStream(peek) : peek;
			try (BufferedReader in = new BufferedReader(new InputStreamReader(new LimitedInput(decoded), StandardCharsets.UTF_8)))
			{
				long consumed = 0;
				String line;
				Scene scene = null;
				double previous = 0;
				while ((line = line(in)) != null)
				{
					if (Thread.currentThread().isInterrupted())
					{
						throw new IOException("Loading cancelled.");
					}
					consumed += line.length() + 1;
					if (consumed > MAX_BYTES || ++recording.rows > 250_000)
					{
						throw new IOException("Recording exceeds the reader budget.");
					}
					if (line.isBlank())
					{
						continue;
					}
					JsonObject row;
					try
					{
						depth(line);
						row = new JsonParser().parse(line).getAsJsonObject();
					}
					catch (RuntimeException e)
					{
						throw new IOException("Invalid JSON at line " + recording.rows + ".", e);
					}
					try
					{
						String type = str(row, "type", "");
						if (scene == null)
						{
							scene = header(recording, row, type);
							continue;
						}
						double t = number(row, "elapsed_s", previous);
						if (t < previous || t < 0 || t > 10800)
						{
							throw new IOException("Invalid recording timeline at line " + recording.rows + ".");
						}
						previous = t;
						recording.duration = t;
						JsonObject p = obj(row, "payload");
						if (RowTypes.SCENE.equals(type))
						{
							if (recording.scenes.size() >= 128)
							{
								throw new IOException("Too many scene changes.");
							}
							scene = new Scene(t, str(p, "dimension", scene.dimension));
							recording.scenes.add(scene);
						}
						else
						{
							parse(recording, scene, type, str(row, "user_id", "player"), t, p);
						}
					}
					catch (IllegalArgumentException | IllegalStateException | IndexOutOfBoundsException e)
					{
						throw new IOException("Invalid recording data at line " + recording.rows + ": " + e.getMessage(), e);
					}
				}
			}
		}
		if (recording.scenes.isEmpty() || samples == 0)
		{
			throw new IOException("The recording has no actor positions to replay.");
		}
		for (Scene scene : recording.scenes)
		{
			for (List<Scenery> track : scene.objects.values())
			{
				track.sort(Comparator.comparingDouble(Scenery::time));
				Scenery previous = null;
				for (Scenery object : track)
				{
					if (previous != null && previous.present && object.present && previous.id == object.id)
					{
						object.animationStart = previous.animationStart;
					}
					previous = object;
				}
			}
			for (Actor actor : scene.actors.values())
			{
				actor.lastAnimationSample = null;
			}
		}
		return recording;
	}

	/** The first row; returns the recording's first scene. */
	private Scene header(Recording recording, JsonObject row, String type) throws IOException
	{
		JsonObject osrs = obj(row, "osrs");
		if (!RowTypes.HEADER.equals(type) || !MccrSession.GAME.equals(str(row, "game", ""))
			|| !MccrSession.FORMAT.equals(str(row, "format", "")))
		{
			throw new IOException("This is not an OSRS Embertide recording (mccr/0.1).");
		}
		recording.revision = integer(osrs, "cache_revision", 0);
		String encoding = str(osrs, "motion_xy", "");
		deltaMotion = MccrFileRecorder.MOTION_XY.equals(encoding);
		if (!encoding.isEmpty() && !deltaMotion)
		{
			throw new IOException("Unsupported motion encoding: " + encoding);
		}
		Scene scene = new Scene(0, str(obj(row, "spatial"), "dimension", "osrs:surface"));
		recording.scenes.add(scene);
		scene.terrain.instance |= bool(osrs, "instance");
		return scene;
	}

	private void parse(Recording r, Scene s, String type, String user, double t, JsonObject p) throws IOException
	{
		switch (type)
		{
			case RowTypes.REGION:
				s.terrain.instance = bool(p, "instance");
				s.terrain.baseX = integer(p, "base_x", 0);
				s.terrain.baseY = integer(p, "base_y", 0);
				break;
			case RowTypes.GROUND:
				if ((groundValues += (long) array(p, "tiles").size() * GroundRows.SIZE) > MAX_GROUND_VALUES)
				{
					s.terrain.truncated = true;
				}
				else
				{
					GroundRows.read(p, s.terrain);
				}
				break;
			case RowTypes.INSTANCE_HEIGHTS:
				if (integer(p, "base_x", 0) != s.terrain.baseX || integer(p, "base_y", 0) != s.terrain.baseY)
				{
					throw new IOException("Instance heights do not match the region");
				}
				s.terrain.instanceHeights[plane(integer(p, "plane", 0))] = grid(array(p, "heights"), 105, 105, -32768, 32768);
				break;
			case RowTypes.PRESENCE:
				actor(s, user).npcId = integer(p, "npc_id", -1);
				break;
			case RowTypes.LIFECYCLE:
				actor(s, str(p, "actor_id", user)).presence.add(new Presence(t, !"left".equals(str(p, "state", ""))));
				break;
			case RowTypes.APPEARANCE:
				if (++appearances > 40_000)
				{
					throw new IOException("Too many appearance changes.");
				}
				r.appearances.computeIfAbsent(user, ignored -> new ArrayList<>()).add(new Appearance(t,
					ints(array(p, "equipment_ids"), 12), ints(array(p, "colors"), 5), bool(p, "female"), integer(p, "transformed_npc_id", -1)));
				break;
			case RowTypes.POSITION:
				position(s, user, t, p);
				break;
			case RowTypes.POSES:
				for (JsonElement e : array(p, "poses"))
				{
					JsonArray a = e.getAsJsonArray();
					if (a.size() < 11)
					{
						throw new IllegalArgumentException("Short pose");
					}
					Actor target = actor(s, a.get(0).getAsString());
					add(target, target.poses, new Sample(t, num(a, 1) + .5, num(a, 2) + .5, plane((int) num(a, 3)),
						(int) num(a, 5), (int) num(a, 6), (int) num(a, 8), (int) num(a, 7), (int) num(a, 10)));
				}
				break;
			case RowTypes.MOTION:
				for (JsonElement e : array(p, "samples"))
				{
					motion(s, t, e.getAsJsonArray());
				}
				break;
			case RowTypes.SNAPSHOT:
				for (JsonElement e : array(p, "cells"))
				{
					cell(s, e.getAsJsonArray());
				}
				break;
			case RowTypes.OBJECT:
				String scope = str(p, "scope", "baseline");
				for (JsonElement e : array(p, "objects"))
				{
					object(s, t, scope, e.getAsJsonObject());
				}
				break;
			default:
				break;
		}
	}

	private void position(Scene s, String user, double t, JsonObject p) throws IOException
	{
		JsonObject o = obj(p, "osrs");
		if (!o.has("world_x") || !o.has("world_y"))
		{
			return;
		}
		Actor actor = actor(s, user);
		add(actor, actor.poses, new Sample(t, number(o, "world_x", 0) + .5, number(o, "world_y", 0) + .5,
			plane(integer(p, "plane", 0)), integer(o, "orientation", 0), integer(o, "animation", -1),
			integer(o, "animation_frame", -1), integer(o, "pose_animation", -1), integer(o, "npc_id", actor.npcId)));
	}

	private void motion(Scene s, double t, JsonArray a) throws IOException
	{
		if (a.size() < 8)
		{
			throw new IllegalArgumentException("Short motion sample");
		}
		String id = a.get(0).getAsString();
		Actor moving = actor(s, id);
		double x = num(a, 1), y = num(a, 2);
		if (deltaMotion)
		{
			if (x != Math.rint(x) || y != Math.rint(y) || Math.abs(x) > 200_000_000 || Math.abs(y) > 200_000_000)
			{
				throw new IOException("Invalid compact motion coordinates");
			}
			long[] last = motionCoordinates.get(id);
			// The recorder keeps this accumulator across scene changes and actor rejoins.
			long[] next = {(long) x + (last == null ? 0 : last[0]), (long) y + (last == null ? 0 : last[1])};
			motionCoordinates.put(id, next);
			x = next[0] / 1000.0;
			y = next[1] / 1000.0;
		}
		add(moving, moving.motion, new Sample(t, x, y, plane((int) num(a, 3)),
			(int) num(a, 4), (int) num(a, 5), (int) num(a, 6), (int) num(a, 7), -1));
	}

	/** A ground cell (x, plane * 8 + elevation, -y) as SceneMapper writes it; osrs:ground is an older recorder's. */
	private void cell(Scene s, JsonArray a) throws IOException
	{
		if (a.size() < 4)
		{
			throw new IllegalArgumentException("Short ground cell");
		}
		String material = a.get(3).getAsString();
		boolean legacy = LEGACY_GROUND.equals(material);
		if (!legacy && !material.startsWith(SceneMapper.UNDERLAY) && !material.startsWith(SceneMapper.OVERLAY))
		{
			return;
		}
		if (!legacy)
		{
			int materialId = Integer.parseInt(material.substring(material.lastIndexOf(':') + 1));
			if (materialId < 0 || materialId > 65535)
			{
				throw new IOException("Invalid ground material ID");
			}
		}
		if (++cells > 100_000)
		{
			throw new IOException("Too many ground cells.");
		}
		int x = (int) num(a, 0), y = -(int) num(a, 2), h = (int) num(a, 1), plane = plane(Math.floorDiv(h, SceneMapper.PLANE_HEIGHT));
		s.ground.put(groundKey(x, y, plane), new Ground(x, y, plane, (h - plane * SceneMapper.PLANE_HEIGHT) * (double) SceneMapper.LOCAL_TILE_SIZE, material));
	}

	private void object(Scene s, double t, String scope, JsonObject j) throws IOException
	{
		// Budgeted per scene as well: a raid loads a new instance per room.
		if (++s.objectEntries > MAX_SCENE_OBJECTS || ++objects > MAX_OBJECTS)
		{
			throw new IOException("Too many scene objects.");
		}
		boolean baseline = "baseline".equals(scope);
		Scenery object = new Scenery(baseline ? s.start : t,
			integer(j, "anchor_x", integer(j, "x", 0)), integer(j, "anchor_y", integer(j, "y", 0)),
			plane(integer(j, "plane", 0)), integer(j, "impostor_id", integer(j, "id", -1)),
			integer(j, "type", 10), integer(j, "orientation", 0) & 3, integer(j, "kind", 0), !"despawned".equals(scope));
		// Impostors may change between spawn and despawn; identity is the original object.
		List<Scenery> track = s.objects.computeIfAbsent(object.key(integer(j, "id", object.id)), ignored -> new ArrayList<>());
		if (!baseline || track.stream().noneMatch(v -> v.t == s.start))
		{
			track.add(object);
		}
	}

	private Actor actor(Scene scene, String id) throws IOException
	{
		if (id.length() > 256)
		{
			throw new IOException("Actor identifier is too long.");
		}
		Actor a = scene.actors.get(id);
		if (a == null)
		{
			if (++actors > 16_384)
			{
				throw new IOException("Too many actors.");
			}
			a = new Actor(id);
			scene.actors.put(id, a);
		}
		return a;
	}

	private int[][] grid(JsonArray array, int width, int height, int min, int max) throws IOException
	{
		if (array.size() != width)
		{
			throw new IOException("Invalid terrain grid width");
		}
		int[][] result = new int[width][];
		for (int x = 0; x < width; x++)
		{
			result[x] = ints(array.get(x).getAsJsonArray(), height);
			if (result[x].length != height)
			{
				throw new IOException("Invalid terrain grid height");
			}
			for (int value : result[x])
			{
				if (value < min || value > max)
				{
					throw new IOException("Invalid terrain grid value");
				}
			}
			if ((terrainValues += height) > 2_000_000)
			{
				throw new IOException("Terrain grid budget exceeded");
			}
		}
		return result;
	}

	private void add(Actor actor, List<Sample> track, Sample sample) throws IOException
	{
		if (++samples > 1_000_000)
		{
			throw new IOException("Too many motion samples.");
		}
		if (Math.abs(sample.x) > 100_000 || Math.abs(sample.y) > 100_000)
		{
			throw new IOException("Invalid actor coordinates.");
		}
		Sample previous = actor.lastAnimationSample;
		Presence lifecycle = actor.presence.isEmpty() ? null : actor.presence.get(actor.presence.size() - 1);
		if (previous != null && previous.plane == sample.plane && sample.t - previous.t < 2
			&& (lifecycle == null || previous.t >= lifecycle.t))
		{
			if (previous.pose == sample.pose)
			{
				sample.poseStart = previous.poseStart;
			}
			if (previous.animation == sample.animation && previous.frame == sample.frame)
			{
				sample.frameStart = previous.frameStart;
			}
		}
		actor.lastAnimationSample = sample;
		track.add(sample);
	}

	private static final class LimitedInput extends FilterInputStream
	{
		private long count;

		LimitedInput(InputStream in) { super(in); }

		@Override
		public int read() throws IOException
		{
			int value = in.read();
			if (value >= 0)
			{
				counted(1);
			}
			return value;
		}

		@Override
		public int read(byte[] bytes, int offset, int length) throws IOException
		{
			int amount = in.read(bytes, offset, length);
			if (amount > 0)
			{
				counted(amount);
			}
			return amount;
		}

		private void counted(int amount) throws IOException
		{
			if ((count += amount) > MAX_BYTES)
			{
				throw new IOException("Decompressed recording exceeds 128 MiB.");
			}
		}
	}

	private static String line(BufferedReader in) throws IOException
	{
		StringBuilder out = new StringBuilder();
		int c;
		while ((c = in.read()) != -1 && c != '\n')
		{
			if (out.length() >= MAX_LINE)
			{
				throw new IOException("A recording line exceeds 2 MiB.");
			}
			out.append((char) c);
		}
		return c == -1 && out.length() == 0 ? null : out.toString();
	}

	private static void depth(String line)
	{
		int depth = 0;
		boolean string = false, escaped = false;
		for (int i = 0; i < line.length(); i++)
		{
			char c = line.charAt(i);
			if (string)
			{
				if (escaped)
				{
					escaped = false;
				}
				else if (c == '\\')
				{
					escaped = true;
				}
				else if (c == '"')
				{
					string = false;
				}
			}
			else if (c == '"')
			{
				string = true;
			}
			else if ((c == '{' || c == '[') && ++depth > 32)
			{
				throw new IllegalArgumentException("JSON nesting exceeds 32");
			}
			else if (c == '}' || c == ']')
			{
				depth--;
			}
		}
	}

	private static int plane(int value)
	{
		if (value < 0 || value > 3)
		{
			throw new IllegalArgumentException("Invalid plane");
		}
		return value;
	}

	private static int[] ints(JsonArray a, int max)
	{
		if (a.size() > max)
		{
			throw new IllegalArgumentException("Appearance array is too long");
		}
		int[] out = new int[a.size()];
		for (int i = 0; i < out.length; i++)
		{
			out[i] = (int) num(a, i);
		}
		return out;
	}

	private static double num(JsonArray a, int i) { return finite(a.get(i).getAsDouble()); }

	private static double finite(double d)
	{
		if (!Double.isFinite(d))
		{
			throw new IllegalArgumentException("Non-finite number");
		}
		return d;
	}

	private static boolean present(JsonObject o, String key) { return o.has(key) && !o.get(key).isJsonNull(); }
	private static double number(JsonObject o, String key, double fallback) { return present(o, key) ? finite(o.get(key).getAsDouble()) : fallback; }
	private static int integer(JsonObject o, String key, int fallback) { return (int) number(o, key, fallback); }
	private static boolean bool(JsonObject o, String key) { return present(o, key) && o.get(key).getAsBoolean(); }
	private static String str(JsonObject o, String key, String fallback) { return present(o, key) ? o.get(key).getAsString() : fallback; }
	private static JsonObject obj(JsonObject o, String key) { return o.has(key) && o.get(key).isJsonObject() ? o.getAsJsonObject(key) : new JsonObject(); }
	private static JsonArray array(JsonObject o, String key) { return o.has(key) && o.get(key).isJsonArray() ? o.getAsJsonArray(key) : new JsonArray(); }
}

package com.extrinsiccognition.embertide.viewer;

import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.RuneLiteObjectController;

/** The recording supplies the animation clock; RuneLite's real-time tick is ignored. */
final class ReplayObject extends RuneLiteObjectController
{
	private final Client client;
	private Model base;
	private Animation action, pose;
	private int actionFrame, poseFrame;
	private double scale = 1;
	private int width = 128, height = 128;

	ReplayObject(Client client) { this.client = client; }

	void model(Model model, double scale, int width, int height)
	{
		if (base != model || this.scale != scale || this.width != width)
		{
			double extent = 0;
			if (model != null && model.getVerticesX() != null && model.getVerticesZ() != null)
			{
				for (int i = 0; i < model.getVerticesCount(); i++)
				{
					extent = Math.max(extent, Math.hypot(model.getVerticesX()[i], model.getVerticesZ()[i]));
				}
			}
			// The software scene renderer needs every covered tile drawn first.
			setRadius(Math.max(60, (int) Math.ceil(extent * scale * width / 128)));
		}
		this.base = model;
		this.scale = scale;
		this.width = width;
		this.height = height;
	}

	void animation(int actionId, int frame, int poseId, double elapsed, double poseElapsed)
	{
		action = load(actionId);
		pose = load(poseId);
		actionFrame = frameAt(action, frame, elapsed);
		poseFrame = frameAt(pose, 0, poseElapsed);
	}

	private Animation load(int id)
	{
		if (id < 0 || id > 1_000_000)
		{
			return null;
		}
		try
		{
			return client.loadAnimation(id);
		}
		catch (RuntimeException ignored)
		{
			return null;
		}
	}

	static int frameAt(Animation animation, int recordedFrame, double elapsed)
	{
		if (animation == null || animation.getDuration() <= 0)
		{
			return 0;
		}
		// Quantize replay seconds to client ticks. The tiny tolerance avoids losing a
		// tick through floating-point subtraction at exact 20 ms sample boundaries.
		long ticks = Double.isFinite(elapsed) ? (long) Math.min(1_000_000_000_000L, Math.max(0, elapsed * 50 + 1e-7)) : 0;
		if (animation.isMayaAnim())
		{
			int duration = animation.getDuration();
			long frame = Math.max(0, Math.min(duration - 1, recordedFrame)) + ticks;
			int loop = loopStart(duration, animation.getFrameStep());
			return frame < duration ? (int) frame : loop + (int) ((frame - duration) % (duration - loop));
		}
		int[] lengths = animation.getFrameLengths();
		if (lengths == null || lengths.length == 0)
		{
			return 0;
		}
		int start = Math.max(0, Math.min(lengths.length - 1, recordedFrame));
		int loop = loopStart(lengths.length, animation.getFrameStep());
		long firstTicks = 0, loopTicks = 0;
		for (int i = 0; i < lengths.length; i++)
		{
			if (lengths[i] <= 0)
			{
				return 0;
			}
			if (i >= start)
			{
				firstTicks += lengths[i];
			}
			if (i >= loop)
			{
				loopTicks += lengths[i];
			}
		}
		// Classic duration counts keyframes, not ticks. Only the sequence's
		// loop suffix repeats, and RuneLite advances when elapsed > frame length.
		if (ticks > firstTicks)
		{
			ticks = 1 + (ticks - firstTicks - 1) % loopTicks;
			start = loop;
		}
		for (int i = start; i < lengths.length; i++)
		{
			if (ticks <= lengths[i])
			{
				return i;
			}
			ticks -= lengths[i];
		}
		return lengths.length - 1;
	}

	private static int loopStart(int frames, int step)
	{
		return step > 0 && step <= frames ? frames - step : 0;
	}

	@Override public Model getModel()
	{
		if (base == null)
		{
			return null;
		}
		// applyTransformations supplies a shared scratch model, which may be returned
		// by controllers. Never resize the cached base, even for a static actor.
		Model result = client.applyTransformations(base, action, actionFrame, pose, poseFrame);
		if (result == null)
		{
			return null;
		}
		if (result != base)
		{
			result.scale(Math.max(1, (int) Math.round(scale * width)), Math.max(1, (int) Math.round(scale * height)), Math.max(1, (int) Math.round(scale * width)));
		}
		return result;
	}
}

package com.extrinsiccognition.embertide.viewer;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.coords.LocalPoint;

/** Owns only its registered projections; never changes the real scene. */
final class ReplayRenderer
{
	static final int DEFAULT_OBJECT_LIMIT = 4096;
	static final int MAX_OBJECT_LIMIT = 8192;
	static final String NO_GROUND = "No ground in this recording, so only figures and objects are shown. Recordings made with an older recorder do not save the ground.";
	static final String PARTIAL_GROUND = "This recording saved the floor only near where you walked. Recordings made with a newer recorder save all of it.";
	private final Client client;
	private final CacheModels models;
	private final Map<String, ReplayObject> rendered = new LinkedHashMap<>();
	private final Map<String, List<Terrain.Tile>> groundPatches = new LinkedHashMap<>();
	private final Map<String, Model> patchModels = new HashMap<>();
	private final Map<String, Long> patchRetryAfter = new HashMap<>();
	private List<Map.Entry<String, List<Recording.Scenery>>> scenery = new ArrayList<>();
	private Recording.Scene scene;
	private Placement placement;
	private int sourcePlane, radius;
	private int waiting, visibleActors, visibleScenery, capped, cappedActors;
	private boolean allFloors;
	private int objectLimit = DEFAULT_OBJECT_LIMIT;

	ReplayRenderer(Client client)
	{
		this.client = client;
		models = new CacheModels(client);
	}

	boolean placed() { return placement != null; }
	Placement placement() { return placement; }
	void objectLimit(int limit) { objectLimit = Math.max(128, Math.min(MAX_OBJECT_LIMIT, limit)); }

	void place(Recording.Scene scene, Recording.Sample origin, LocalPoint anchor, int plane, int anchorZ,
		boolean miniature, int size, int radius, int rotation, int lift, boolean surround, int extraArea, boolean allFloors)
	{
		clear();
		this.scene = scene;
		this.allFloors = allFloors;
		models.snapshotGround(scene);
		radius = Math.max(4, Math.min(24, radius)) + (surround ? Math.max(0, Math.min(24, extraArea)) : 0);
		this.radius = radius;
		sourcePlane = origin.plane;
		double scale = miniature ? size / (2.0 * radius + 1) : 1;
		placement = new Placement(origin.x, origin.y, scene.height(origin.x, origin.y, sourcePlane), scale,
			anchor.getX(), anchor.getY(), anchorZ - lift, plane, anchor.getWorldView(), rotation);
		for (int p = allFloors ? 0 : sourcePlane; p <= (allFloors ? 3 : sourcePlane); p++)
		{
			for (int x = (int) Math.ceil(origin.x - radius - .5); x <= Math.floor(origin.x + radius - .5); x++)
			{
				for (int y = (int) Math.ceil(origin.y - radius - .5); y <= Math.floor(origin.y + radius - .5); y++)
				{
					Terrain.Tile tile = scene.terrain.tile(x, y, p, allFloors);
					if (tile != null)
					{
						String key = p + ":" + Math.floorDiv(x, 4) + ":" + Math.floorDiv(y, 4);
						groundPatches.computeIfAbsent(key, ignored -> new ArrayList<>()).add(tile);
					}
				}
			}
		}
		List<Map.Entry<String, List<Terrain.Tile>>> patches = new ArrayList<>(groundPatches.entrySet());
		patches.sort(Comparator.comparingDouble(e -> distance(e.getValue().get(0).x, e.getValue().get(0).y)));
		groundPatches.clear();
		patches.forEach(e -> groundPatches.put(e.getKey(), e.getValue()));
		scenery = new ArrayList<>(scene.objects.entrySet());
		scenery.sort(Comparator.comparingDouble(e -> distance(e.getValue().get(0).x, e.getValue().get(0).y)));
	}

	void draw(Recording recording, double time, boolean showGround, boolean showScenery)
	{
		if (placement == null)
		{
			return;
		}
		models.beginTick();
		waiting = visibleActors = visibleScenery = capped = cappedActors = 0;
		Set<String> keep = new HashSet<>();
		drawActors(recording, time, keep);
		if (showGround)
		{
			drawGround(keep);
		}
		if (showScenery)
		{
			drawScenery(time, keep);
		}
		rendered.entrySet().removeIf(entry ->
		{
			if (keep.contains(entry.getKey()))
			{
				return false;
			}
			client.removeRuneLiteObject(entry.getValue());
			return true;
		});
	}

	private void drawActors(Recording recording, double time, Set<String> keep)
	{
		List<ActorAt> actors = new ArrayList<>();
		for (Recording.Actor actor : scene.actors.values())
		{
			Recording.Sample sample = actor.sample(time);
			if (sample != null && (allFloors || sample.plane == sourcePlane) && inRange(sample.x, sample.y))
			{
				actors.add(new ActorAt(actor, sample));
			}
		}
		actors.sort(Comparator.comparingDouble(a -> "player".equals(a.actor.id) ? -1 : distance(a.sample.x, a.sample.y)));
		int count = 0;
		for (ActorAt at : actors)
		{
			if (count++ >= 128)
			{
				cappedActors++;
				continue;
			}
			Recording.Sample sample = at.sample;
			Recording.Appearance appearance = recording.appearance(at.actor.id, time);
			int npcId = sample.npcId >= 0 ? sample.npcId : at.actor.npcId;
			if (appearance != null && appearance.npcId >= 0)
			{
				npcId = appearance.npcId;
			}
			Animation animation = sample.animation < 0 ? null : client.loadAnimation(sample.animation);
			Model model = models.actor(appearance, npcId, animation == null ? -1 : animation.getLeftHandItem(), animation == null ? -1 : animation.getRightHandItem());
			if (model == null)
			{
				waiting++;
				continue;
			}
			String key = "actor:" + at.actor.id;
			ReplayObject object = get(key);
			object.model(model, placement.scale, npcId >= 0 ? models.npcWidth(npcId) : 128, npcId >= 0 ? models.npcHeight(npcId) : 128);
			object.animation(sample.animation, sample.frame, sample.pose, time - sample.frameStart, time - sample.poseStart);
			if (position(object, sample.x, sample.y, scene.height(sample.x, sample.y, sample.plane), sample.orientation))
			{
				keep.add(key);
				visibleActors++;
			}
		}
	}

	/** Builds at most one missing patch model a tick. */
	private void drawGround(Set<String> keep)
	{
		boolean built = false;
		for (Map.Entry<String, List<Terrain.Tile>> patch : groundPatches.entrySet())
		{
			Terrain.Tile first = patch.getValue().get(0);
			double patchX = Math.floorDiv(first.x, 4) * 4 + 2, patchY = Math.floorDiv(first.y, 4) * 4 + 2;
			Model model = patchModels.get(patch.getKey());
			if (model == null && !built && System.nanoTime() >= patchRetryAfter.getOrDefault(patch.getKey(), 0L))
			{
				built = true;
				model = models.groundPatch(patch.getValue(), patchX, patchY, placement.sourceHeight);
				if (model != null)
				{
					patchModels.put(patch.getKey(), model);
				}
				else
				{
					patchRetryAfter.put(patch.getKey(), System.nanoTime() + 2_000_000_000L);
				}
			}
			if (model == null)
			{
				waiting++;
				continue;
			}
			String key = "ground:" + patch.getKey();
			ReplayObject object = get(key);
			object.model(model, placement.scale, 128, 128);
			object.animation(-1, 0, -1, 0, 0);
			if (position(object, patchX, patchY, placement.sourceHeight, 0))
			{
				keep.add(key);
			}
		}
	}

	private void drawScenery(double time, Set<String> keep)
	{
		int count = 0;
		for (Map.Entry<String, List<Recording.Scenery>> entry : scenery)
		{
			Recording.Scenery recorded = Recording.at(entry.getValue(), time);
			if (recorded == null || !recorded.present || (!allFloors && recorded.plane != sourcePlane)
				|| !inRange(recorded.x + .5, recorded.y + .5) || models.emptyScenery(recorded))
			{
				continue;
			}
			if (count >= objectLimit)
			{
				capped++;
				continue;
			}
			Model model = models.scenery(recorded);
			if (model == null && models.emptyScenery(recorded))
			{
				continue;
			}
			count++;
			if (model == null)
			{
				waiting++;
				continue;
			}
			Definitions.ObjectDef definition = models.definition(recorded.id);
			double sizeX = definition == null ? 1 : definition.sizeX, sizeY = definition == null ? 1 : definition.sizeY;
			if ((recorded.orientation & 1) != 0)
			{
				double tmp = sizeX;
				sizeX = sizeY;
				sizeY = tmp;
			}
			// Ground decorations and walls stay centred on their anchor tile.
			if (recorded.kind != 0)
			{
				sizeX = sizeY = 1;
			}
			double x = recorded.x + sizeX / 2, y = recorded.y + sizeY / 2;
			String key = "object:" + entry.getKey();
			ReplayObject object = get(key);
			object.model(model, placement.scale, 128, 128);
			object.animation(definition == null ? -1 : definition.animation, 0, -1, time - recorded.animationStart, 0);
			if (position(object, x, y, scene.height(x, y, recorded.plane), 0))
			{
				keep.add(key);
				visibleScenery++;
			}
		}
	}

	private ReplayObject get(String key) { return rendered.computeIfAbsent(key, ignored -> new ReplayObject(client)); }

	private boolean position(ReplayObject object, double x, double y, double height, int orientation)
	{
		int localX = placement.x(x, y), localY = placement.y(x, y);
		if (localX < 128 || localY < 128 || localX >= 103 * 128 || localY >= 103 * 128)
		{
			return false;
		}
		object.setLocation(new LocalPoint(localX, localY, placement.worldView), placement.plane);
		object.setZ(placement.z(height));
		object.setOrientation(placement.orientation(orientation));
		if (!client.isRuneLiteObjectRegistered(object))
		{
			client.registerRuneLiteObject(object);
		}
		return true;
	}

	private double distance(double x, double y) { return Math.hypot(x - placement.sourceX, y - placement.sourceY); }

	private boolean inRange(double x, double y)
	{
		return Math.abs(x - placement.sourceX) <= radius + .5 && Math.abs(y - placement.sourceY) <= radius + .5;
	}

	String status()
	{
		return visibleActors + " actors · " + visibleScenery + " objects"
			+ (allFloors && placement != null ? " · All floors" : "")
			+ (waiting == 0 ? "" : " · " + waiting + " assets pending/unavailable")
			+ (cappedActors == 0 ? "" : " · " + cappedActors + " actors over display limit")
			+ (capped == 0 ? "" : " · " + capped + " objects not shown; raise Object limit in the settings (" + objectLimit + ")")
			+ (scene == null ? "" : !scene.terrain.recorded() ? " · " + NO_GROUND : scene.terrain.sampled ? " · " + PARTIAL_GROUND : "")
			+ (scene == null || !scene.terrain.truncated ? "" : " · Part of the ground was too large to load")
			+ (models.mismatchedGround() == 0 ? "" : " · " + models.mismatchedGround() + " ground tiles could not be drawn")
			+ (models.lastProblem().isEmpty() ? "" : " · " + models.lastProblem());
	}

	void clear()
	{
		for (ReplayObject object : rendered.values())
		{
			client.removeRuneLiteObject(object);
		}
		rendered.clear();
		groundPatches.clear();
		patchModels.clear();
		patchRetryAfter.clear();
		scenery.clear();
		scene = null;
		placement = null;
		waiting = visibleActors = visibleScenery = capped = cappedActors = 0;
	}

	void close()
	{
		clear();
		models.clear();
	}

	private static final class ActorAt
	{
		final Recording.Actor actor;
		final Recording.Sample sample;

		ActorAt(Recording.Actor actor, Recording.Sample sample)
		{
			this.actor = actor;
			this.sample = sample;
		}
	}
}

package com.extrinsiccognition.embertide.viewer;

import java.util.HashMap;
import java.util.Map;
import java.util.function.IntFunction;
import static com.extrinsiccognition.embertide.SceneMapper.OVERLAY;
import static com.extrinsiccognition.embertide.SceneMapper.UNDERLAY;

/**
 * Floor for a scene recorded before osrs.ground rows: its spatial snapshot cells, which name each tile's underlay or
 * overlay near where the player walked, coloured from the client's own definitions the way the client colours a
 * tile. Cells store a rounded height clamped to a plane, so corners use saved instance heights where they exist.
 * Underlays blend over the neighbouring recorded underlays (the client's 11 by 11 window); hidden overlays and tiles
 * with neither draw nothing, and object shadows are not reproduced. Runs on the client thread.
 */
final class SnapshotTerrain
{
	static final int BLEND = 5;

	private SnapshotTerrain() { }

	/** Whether a cell names an underlay or overlay; id 0 is a tile with neither. */
	static boolean names(String material)
	{
		return (material.startsWith(UNDERLAY) || material.startsWith(OVERLAY)) && !material.endsWith(":0");
	}

	/** Fills the scene's terrain from its cells once; osrs.ground rows win. Returns the tiles added. */
	static int build(Recording.Scene scene, IntFunction<Definitions.UnderlayDef> underlays, IntFunction<Definitions.OverlayDef> overlays)
	{
		Terrain terrain = scene.terrain;
		if (terrain.sampled || terrain.recorded() || scene.ground.isEmpty())
		{
			return 0;
		}
		terrain.sampled = true;
		// {overlay?, definition id, client height (negative up)}, keyed per plane and tile.
		Map<Long, int[]> cells = new HashMap<>();
		for (Recording.Ground g : scene.ground.values())
		{
			if (!names(g.material))
			{
				continue;
			}
			boolean overlay = g.material.startsWith(OVERLAY);
			// Tiles store definition id plus one.
			int stored = Integer.parseInt(g.material.substring(g.material.lastIndexOf(':') + 1));
			cells.put(key(g.plane, g.x, g.y), new int[]{overlay ? 1 : 0, stored - 1, (int) -Math.round(g.height)});
		}
		for (Map.Entry<Long, int[]> e : cells.entrySet())
		{
			int plane = plane(e.getKey()), x = x(e.getKey()), y = y(e.getKey());
			for (int c = 0; c < 4; c++) { corner(terrain, cells, plane, x + (c == 1 || c == 2 ? 1 : 0), y + (c >= 2 ? 1 : 0)); }
		}
		int added = 0;
		for (Map.Entry<Long, int[]> e : cells.entrySet())
		{
			int plane = plane(e.getKey()), x = x(e.getKey()), y = y(e.getKey());
			int[] cell = e.getValue();
			int hsl, texture = -1;
			if (cell[0] == 1)
			{
				Definitions.OverlayDef d = overlays.apply(cell[1]);
				if (d == null || d.hidden())
				{
					continue;
				}
				texture = d.texture;
				hsl = texture >= 0 ? -1 : packHsl(d.hue, d.saturation, d.lightness);
			}
			else
			{
				hsl = blendedUnderlay(cells, underlays, plane, x, y);
				if (hsl == Integer.MIN_VALUE)
				{
					continue;
				}
			}
			int[] entry = {0, 0, 0, 0, 0, texture};
			for (int c = 0; c < 4; c++)
			{
				entry[1 + c] = shade(hsl, light(terrain, plane, x + (c == 1 || c == 2 ? 1 : 0), y + (c >= 2 ? 1 : 0)));
			}
			terrain.tile(plane, x, y, entry);
			added++;
		}
		return added;
	}

	/** A tile's south-west corner is its own cell's height; a corner without one averages the cells that share it. */
	private static void corner(Terrain terrain, Map<Long, int[]> cells, int plane, int x, int y)
	{
		if (Double.isFinite(terrain.height(x, y, plane, true)))
		{
			return;
		}
		int[] own = cells.get(key(plane, x, y));
		if (own != null)
		{
			terrain.corner(plane, x, y, own[2]);
			return;
		}
		int sum = 0, n = 0;
		for (int dx = -1; dx <= 0; dx++)
		{
			for (int dy = -1; dy <= 0; dy++)
			{
				int[] c = cells.get(key(plane, x + dx, y + dy));
				if (c != null)
				{
					sum += c[2];
					n++;
				}
			}
		}
		if (n > 0)
		{
			terrain.corner(plane, x, y, Math.round(sum / (float) n));
		}
	}

	private static int blendedUnderlay(Map<Long, int[]> cells, IntFunction<Definitions.UnderlayDef> underlays, int plane, int x, int y)
	{
		long hue = 0, multiplier = 0, saturation = 0, lightness = 0;
		int count = 0;
		for (int dx = -BLEND; dx <= BLEND; dx++)
		{
			for (int dy = -BLEND; dy <= BLEND; dy++)
			{
				int[] c = cells.get(key(plane, x + dx, y + dy));
				if (c == null || c[0] != 0)
				{
					continue;
				}
				Definitions.UnderlayDef d = underlays.apply(c[1]);
				if (d == null)
				{
					continue;
				}
				hue += d.hue;
				multiplier += d.hueMultiplier;
				saturation += d.saturation;
				lightness += d.lightness;
				count++;
			}
		}
		if (count == 0 || multiplier == 0 || underlays.apply(cells.get(key(plane, x, y))[1]) == null)
		{
			return Integer.MIN_VALUE;
		}
		return packHsl((int) (hue * 256 / multiplier), (int) (saturation / count), (int) (lightness / count));
	}

	/** The client's terrain light at a corner from the slope of its neighbours, without object shadows; 84 when flat. */
	static int light(Terrain terrain, int plane, int x, int y)
	{
		int here = raw(terrain, plane, x, y, 0);
		int dx = raw(terrain, plane, x + 1, y, here) - raw(terrain, plane, x - 1, y, here);
		int dy = raw(terrain, plane, x, y + 1, here) - raw(terrain, plane, x, y - 1, here);
		int length = (int) Math.sqrt(dx * dx + dy * dy + 65536);
		int nx = (dx << 8) / length, ny = 65536 / length, nz = (dy << 8) / length;
		return (nx * -50 + ny * -10 + nz * -50) / 213 + 96;
	}

	private static int raw(Terrain terrain, int plane, int x, int y, int fallback)
	{
		double h = terrain.height(x, y, plane, true);
		return Double.isFinite(h) ? (int) -h : fallback;
	}

	/** The client's packed terrain HSL: saturation halves as lightness rises. */
	static int packHsl(int hue, int saturation, int lightness)
	{
		if (lightness > 179)
		{
			saturation /= 2;
		}
		if (lightness > 192)
		{
			saturation /= 2;
		}
		if (lightness > 217)
		{
			saturation /= 2;
		}
		if (lightness > 243)
		{
			saturation /= 2;
		}
		return (hue / 4 << 10) + (saturation / 32 << 7) + lightness / 2;
	}

	/** A colour lit at a corner; a textured face (hsl -1) keeps only the light, as the client draws it. */
	static int shade(int hsl, int light)
	{
		if (hsl == -1)
		{
			return Math.max(2, Math.min(126, light));
		}
		int l = Math.max(2, Math.min(126, (hsl & 127) * light / 128));
		return (hsl & 0xff80) + l;
	}

	private static long key(int plane, int x, int y) { return (long) plane << 48 | (long) (x & 0xffffff) << 24 | (y & 0xffffff); }
	private static int plane(long key) { return (int) (key >>> 48); }
	private static int x(long key) { return (int) (key >>> 24 & 0xffffff); }
	private static int y(long key) { return (int) (key & 0xffffff); }
}

package com.extrinsiccognition.embertide.viewer;

import com.extrinsiccognition.embertide.GroundRows;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

/**
 * The ground a recording saved: its osrs.ground rows, keyed by world tile and map plane, or for older recordings a floor
 * SnapshotTerrain builds once from snapshot cells on the client thread. Otherwise immutable during playback.
 * Each scene load the recorder wrote replaces the tiles it covered.
 */
final class Terrain implements GroundRows.Sink
{
	static final int MAX_TILES = 600_000, MAX_BLOCKS = 1024;
	boolean instance;
	int baseX, baseY;
	/** Heights written for old instance recordings, before ground rows; [plane][scene x][scene y]. */
	final int[][][] instanceHeights = new int[4][][];
	private final Map<Long, Block> blocks = new HashMap<>();
	private int tiles;
	/** Ground past the budget is left out; a long walk keeps its first areas. */
	boolean truncated;

	/** Whether this scene has ground: osrs.ground rows, or a floor built from snapshot cells. */
	boolean recorded() { return !blocks.isEmpty(); }
	/** The floor was built from spatial snapshot cells (a recording made before osrs.ground rows), or that was tried. */
	boolean sampled;

	@Override
	public void tile(int plane, int x, int y, int[] entry)
	{
		Block block = block(plane, x, y, true);
		if (block == null)
		{
			return;
		}
		int i = index(x, y);
		if (block.tiles[i] == null && entry != null)
		{
			if (tiles >= MAX_TILES)
			{
				truncated = true;
				return;
			}
			tiles++;
		}
		else if (block.tiles[i] != null && entry == null)
		{
			tiles--;
		}
		block.tiles[i] = entry;
	}

	@Override
	public void corner(int plane, int x, int y, int height)
	{
		Block block = block(plane, x, y, true);
		if (block != null)
		{
			block.heights[index(x, y)] = height;
		}
	}

	@Override
	public void bridge(int x, int y)
	{
		Block block = block(1, x, y, true);
		if (block != null)
		{
			block.bridge[index(x, y)] = true;
		}
	}

	private boolean isBridge(int x, int y)
	{
		Block block = block(1, x, y, false);
		return block != null && block.bridge[index(x, y)];
	}

	Tile tile(int x, int y, int plane) { return tile(x, y, plane, false); }

	/** physicalPlane reads the map plane itself, without moving a bridge up to the plane it is drawn on. */
	Tile tile(int x, int y, int plane, boolean physicalPlane)
	{
		if (plane < 0 || plane > 3)
		{
			return null;
		}
		int p = mapPlane(x, y, plane, physicalPlane);
		Block block = block(p, x, y, false);
		int[] entry = block == null ? null : block.tiles[index(x, y)];
		if (entry == null)
		{
			return null;
		}
		double[] heights = {height(x, y, p, true), height(x + 1, y, p, true), height(x + 1, y + 1, p, true), height(x, y + 1, p, true)};
		for (double h : heights)
		{
			if (!Double.isFinite(h))
			{
				return null;
			}
		}
		return new Tile(x, y, plane, entry, heights, physicalPlane);
	}

	double height(int x, int y, int plane) { return height(x, y, plane, false); }

	/** Corner height, up positive, or NaN where nothing was recorded. */
	double height(int x, int y, int plane, boolean physicalPlane)
	{
		if (plane < 0 || plane > 3)
		{
			return Double.NaN;
		}
		int p = mapPlane(x, y, plane, physicalPlane);
		Block block = block(p, x, y, false);
		int h = block == null ? Integer.MIN_VALUE : block.heights[index(x, y)];
		if (h != Integer.MIN_VALUE)
		{
			return -h;
		}
		int[][] grid = instance ? instanceHeights[plane] : null;
		int dx = x - baseX, dy = y - baseY;
		return grid != null && dx >= 0 && dx < grid.length && grid[dx] != null && dy >= 0 && dy < grid[dx].length
			? -grid[dx][dy] : Double.NaN;
	}

	/** Height inside a tile, interpolated between its recorded corners. */
	double surface(double x, double y, int plane)
	{
		int tx = (int) Math.floor(x), ty = (int) Math.floor(y);
		double fx = x - tx, fy = y - ty;
		double a = height(tx, ty, plane), b = height(tx + 1, ty, plane), c = height(tx + 1, ty + 1, plane), d = height(tx, ty + 1, plane);
		return (a * (1 - fx) + b * fx) * (1 - fy) + (d * (1 - fx) + c * fx) * fy;
	}

	private int mapPlane(int x, int y, int plane, boolean physicalPlane)
	{
		return !physicalPlane && plane < 3 && isBridge(x, y) ? plane + 1 : plane;
	}

	private Block block(int plane, int x, int y, boolean create)
	{
		long key = (long) plane << 40 | (long) (x >> 6 & 0xfffff) << 20 | (y >> 6 & 0xfffff);
		Block block = blocks.get(key);
		if (block == null && create)
		{
			if (blocks.size() >= MAX_BLOCKS)
			{
				truncated = true;
				return null;
			}
			block = new Block();
			blocks.put(key, block);
		}
		return block;
	}

	private static int index(int x, int y) { return (x & 63) << 6 | (y & 63); }

	private static final class Block
	{
		final int[][] tiles = new int[4096][];
		final int[] heights = new int[4096];
		final boolean[] bridge = new boolean[4096];
		Block() { Arrays.fill(heights, Integer.MIN_VALUE); }
	}

	static final class Tile
	{
		final int x, y, plane;
		final int[] entry;
		final double[] heights;
		final boolean physicalPlane;
		Tile(int x, int y, int plane, int[] entry, double[] heights, boolean physicalPlane)
		{ this.x = x; this.y = y; this.plane = plane; this.entry = entry; this.heights = heights; this.physicalPlane = physicalPlane; }
		boolean paint() { return entry[0] == 0; }
		int shape() { return entry[0]; }
		int rotation() { return paint() ? 0 : entry[1]; }
		int faces() { return paint() ? 2 : (entry.length - 2) / 4; }

		double height(double x, double y)
		{ return (heights[0] * (1 - x) + heights[1] * x) * (1 - y) + (heights[3] * (1 - x) + heights[2] * x) * y; }
	}
}

package com.extrinsiccognition.embertide.viewer;

import com.extrinsiccognition.embertide.GroundRows;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;

/** Converts recorded ground tiles into private native models, with the colours and textures the client drew. */
final class TerrainModels
{
	private final Client client;
	private ModelData template;
	private int[] faceVertices, uvVertices;
	private int mismatched;
	TerrainModels(Client client) { this.client = client; }

	void clear()
	{
		template = null;
		mismatched = 0;
	}

	/** Shaped tiles whose recorded face count does not match the mask; they are left out. */
	int mismatched() { return mismatched; }

	Model patch(List<Terrain.Tile> tiles, double originX, double originY, double originHeight)
	{
		if (!template())
		{
			return null;
		}
		List<ModelData> parts = new ArrayList<>();
		List<int[]> colours = new ArrayList<>();
		for (Terrain.Tile tile : tiles)
		{
			List<TileGeometry.Face> faces = TileGeometry.faces(tile.paint() ? 0 : tile.shape(), tile.rotation());
			if (faces.size() != tile.faces())
			{
				mismatched++;
				continue;
			}
			for (int f = 0; f < faces.size(); f++)
			{
				TileGeometry.Face face = faces.get(f);
				int[] hsl = new int[3];
				int texture;
				if (tile.paint())
				{
					// Paint vertices are tile corners: SW, SE, NE, NW are entry[1..4].
					for (int i = 0; i < 3; i++) { hsl[i] = tile.entry[1 + face.vertices[i].cornerA]; }
					texture = tile.entry[5];
					if (hsl[0] == GroundRows.HIDDEN || hsl[1] == GroundRows.HIDDEN || hsl[2] == GroundRows.HIDDEN)
					{
						continue;
					}
				}
				else
				{
					int at = 2 + f * 4;
					hsl[0] = tile.entry[at];
					hsl[1] = tile.entry[at + 1];
					hsl[2] = tile.entry[at + 2];
					texture = tile.entry[at + 3];
					if (hsl[0] == GroundRows.HIDDEN)
					{
						continue;
					}
				}
				// Indices belong to our template and stay immutable. Only mutable arrays are cloned.
				ModelData part = template.shallowCopy().cloneVertices().cloneColors().cloneTextures().cloneTransparencies();
				part.getFaceTextures()[0] = (short) texture;
				part.getFaceColors()[0] = (short) (texture >= 0 ? 127 : hsl[0]);
				if (part.getFaceTransparencies() != null)
				{
					Arrays.fill(part.getFaceTransparencies(), (byte) 0);
				}
				int[] shades = new int[3];
				for (int i = 0; i < 3; i++)
				{
					TileGeometry.Vertex v = face.vertices[i];
					vertex(part, faceVertices[i], (tile.x - originX) * 128 + v.x, originHeight - v.interpolate(tile.heights), (tile.y - originY) * 128 + v.z);
					// A textured face keeps only the lightness of its recorded colour.
					shades[i] = texture >= 0 ? clamp(hsl[i] & 127, 2, 126) : hsl[i];
				}
				// Every triangle in this tile uses the same UV plane, including rotated partial overlays.
				vertex(part, uvVertices[0], (tile.x - originX) * 128, originHeight - tile.heights[0], (tile.y - originY) * 128);
				vertex(part, uvVertices[1], (tile.x + 1 - originX) * 128, originHeight - tile.heights[1], (tile.y - originY) * 128);
				vertex(part, uvVertices[2], (tile.x - originX) * 128, originHeight - tile.heights[3], (tile.y + 1 - originY) * 128);
				parts.add(part);
				colours.add(shades);
			}
		}
		if (parts.isEmpty())
		{
			Model empty = client.mergeModels(template).light();
			Arrays.fill(empty.getFaceColors3(), -2);
			return empty;
		}
		if (parts.size() > 240)
		{
			throw new IllegalArgumentException("Terrain patch exceeds texture-index budget");
		}
		Model model = client.mergeModels(parts.toArray(new ModelData[0])).light();
		for (int i = 0; i < colours.size(); i++)
		{
			int[] shades = colours.get(i);
			model.getFaceColors1()[i * 2] = shades[0];
			model.getFaceColors2()[i * 2] = shades[1];
			model.getFaceColors3()[i * 2] = shades[2];
			model.getFaceColors3()[i * 2 + 1] = -2; // Spare allocation face is degenerate and invisible.
		}
		return model;
	}

	private boolean template()
	{
		if (template != null)
		{
			return true;
		}
		ModelData textured = client.loadModelData(3728), triangle = client.loadModelData(823);
		if (textured == null || triangle == null)
		{
			return false;
		}
		// The spare triangle allocates three face vertices independently of the donor's UV vertices.
		ModelData copy = client.mergeModels(textured, triangle);
		Model probe = copy.light();
		if (copy.getFaceCount() != 2 || copy.getVerticesCount() < 6 || copy.getFaceTextures() == null
			|| probe.getTextureFaces() == null || probe.getTexIndices1() == null)
		{
			throw new IllegalStateException("Textured terrain template changed in this cache");
		}
		int texture = probe.getTextureFaces()[0] & 255;
		uvVertices = new int[]{probe.getTexIndices1()[texture], probe.getTexIndices2()[texture], probe.getTexIndices3()[texture]};
		faceVertices = new int[3];
		int count = 0;
		for (int i = 0; i < copy.getVerticesCount() && count < 3; i++)
		{
			if (i != uvVertices[0] && i != uvVertices[1] && i != uvVertices[2])
			{
				faceVertices[count++] = i;
			}
		}
		if (count != 3)
		{
			throw new IllegalStateException("Terrain UV vertices overlap the face");
		}
		copy.getFaceIndices1()[0] = faceVertices[0];
		copy.getFaceIndices2()[0] = faceVertices[1];
		copy.getFaceIndices3()[0] = faceVertices[2];
		copy.getFaceIndices1()[1] = copy.getFaceIndices2()[1] = copy.getFaceIndices3()[1] = uvVertices[0];
		template = copy;
		return true;
	}

	private static void vertex(ModelData model, int i, double x, double y, double z)
	{
		model.getVerticesX()[i] = (float) x;
		model.getVerticesY()[i] = (float) y;
		model.getVerticesZ()[i] = (float) z;
	}

	private static int clamp(int value, int min, int max) { return Math.max(min, Math.min(max, value)); }
}

package com.extrinsiccognition.embertide.viewer;

import java.util.ArrayList;
import java.util.List;

/** The thirteen cache tile masks. Coordinates use a 128-unit tile, north is +z. */
final class TileGeometry
{
	private static final int[][] VERTICES = {
		{1,3,5,7}, {1,3,5,7}, {1,3,5,7}, {1,3,5,7,6}, {1,3,5,7,6}, {1,3,5,7,6},
		{1,3,5,7,6}, {1,3,5,7,2,6}, {1,3,5,7,2,8}, {1,3,5,7,2,8},
		{1,3,5,7,11,12}, {1,3,5,7,11,12}, {1,3,5,7,13,14}
	};
	// Entries are material (0 underlay, 1 overlay), then three vertex indices.
	private static final int[][] FACES = {
		{0,1,2,3,0,0,1,3}, {1,1,2,3,1,0,1,3}, {0,1,2,3,1,0,1,3},
		{0,0,1,2,0,0,2,4,1,0,4,3}, {0,0,1,4,0,0,4,3,1,1,2,4},
		{0,0,4,3,1,0,1,2,1,0,2,4}, {0,1,2,4,1,0,1,4,1,0,4,3},
		{0,4,1,2,0,4,2,5,1,0,4,5,1,0,5,3}, {0,4,1,2,0,4,2,3,0,4,3,5,1,0,4,5},
		{0,0,4,5,1,4,1,2,1,4,2,3,1,4,3,5},
		{0,0,1,5,0,1,4,5,0,1,2,4,1,0,5,3,1,5,4,3,1,4,2,3},
		{1,0,1,5,1,1,4,5,1,1,2,4,0,0,5,3,0,5,4,3,0,4,2,3},
		{1,0,5,4,1,0,1,5,0,0,4,3,0,4,5,3,0,5,2,3,0,1,2,5}
	};
	private static final int[][] POINTS = {
		{0,0}, {64,0}, {128,0}, {128,64}, {128,128}, {64,128}, {0,128}, {0,64},
		{64,32}, {96,64}, {64,96}, {32,64}, {32,32}, {96,32}, {96,96}, {32,96}
	};

	static List<Face> faces(int shape, int rotation)
	{
		if (shape < 0 || shape >= VERTICES.length)
		{
			throw new IllegalArgumentException("Unknown floor shape " + shape);
		}
		Vertex[] vertices = new Vertex[VERTICES[shape].length];
		for (int i = 0; i < vertices.length; i++)
		{
			int code = VERTICES[shape][i];
			if (code <= 8 && (code & 1) == 0)
			{
				code = ((code - 2 * rotation - 1) & 7) + 1;
			}
			else if (code > 8 && code <= 12)
			{
				code = ((code - 9 - rotation) & 3) + 9;
			}
			else if (code > 12)
			{
				code = ((code - 13 - rotation) & 3) + 13;
			}
			int corner = code <= 8 ? (code - 1) / 2 : code <= 12 ? code - 9 : code - 13;
			boolean midpoint = code <= 8 ? (code & 1) == 0 : code <= 12;
			vertices[i] = new Vertex(POINTS[code - 1][0], POINTS[code - 1][1], corner, midpoint ? (corner + 1) & 3 : corner);
		}
		List<Face> result = new ArrayList<>();
		int[] mask = FACES[shape];
		for (int i = 0; i < mask.length; i += 4)
		{
			Vertex[] points = new Vertex[3];
			for (int j = 0; j < 3; j++)
			{
				int index = mask[i + 1 + j];
				points[j] = vertices[index < 4 ? (index - rotation) & 3 : index];
			}
			result.add(new Face(mask[i] == 1, points));
		}
		return result;
	}
	static final class Vertex
	{
		final int x, z, cornerA, cornerB;

		Vertex(int x, int z, int a, int b)
		{
			this.x = x;
			this.z = z;
			cornerA = a;
			cornerB = b;
		}

		double interpolate(double[] values) { return (values[cornerA] + values[cornerB]) / 2; }
	}
	static final class Face
	{
		final boolean overlay; final Vertex[] vertices;

		Face(boolean overlay, Vertex[] vertices)
		{
			this.overlay = overlay;
			this.vertices = vertices;
		}
	}
}

package com.extrinsiccognition.embertide.viewer;

import com.extrinsiccognition.embertide.EmbertideConfig;
import java.awt.Component;
import java.io.IOException;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.atomic.AtomicLong;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import javax.inject.Inject;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.Perspective;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOpened;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** Plays a saved recording back in your POH. The plugin starts and stops it and registers it for events. */
public class Viewer
{
	private static final Logger LOG = LoggerFactory.getLogger(Viewer.class);
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private RenderCallbackManager renderCallbacks;
	@Inject private EmbertideConfig config;
	private volatile boolean enabled;
	private volatile WatchPanel panel;
	private volatile Filepath folder;
	private ExecutorService worker;
	private Future<?> loadTask;
	private final AtomicLong generation = new AtomicLong();
	private final AtomicLong lifecycle = new AtomicLong();
	private final PlaybackClock clock = new PlaybackClock();
	private ReplayRenderer renderer;
	private HouseIsolation isolation;
	private Recording recording;
	private Recording.Scene selectedScene;
	private Recording.Sample sourceOrigin;
	private boolean house, loading;
	private boolean miniature = true, ground = true, scenery = true;
	private boolean hideSurroundings = true;
	private boolean surroundingMap;
	private boolean allFloors = true;
	private int extraArea = 12;
	private int size = 4, radius = 12, lift = 96, rotation;
	private int baseX, baseY, world;
	private long nextUi;
	private String filename = "", message = "";

	public void startUp()
	{
		lifecycle.incrementAndGet();
		enabled = true;
		miniature = hideSurroundings = true;
		rotation = 0;
		clock.speed(1, System.nanoTime());
		clock.loop(true);
		filename = "";
		message = "";
		worker = Executors.newSingleThreadExecutor(task ->
		{
			Thread thread = new Thread(task, "Embertide recording reader");
			thread.setDaemon(true);
			return thread;
		});
		renderer = new ReplayRenderer(client);
		readConfig();
		isolation = new HouseIsolation(client, renderCallbacks);
		onClient(() ->
		{
			house = HouseGate.containsHouse(client.getTopLevelWorldView());
			publish();
		});
	}

	public void shutDown()
	{
		enabled = false;
		generation.incrementAndGet();
		lifecycle.incrementAndGet();
		if (loadTask != null)
		{
			loadTask.cancel(true);
		}
		if (worker != null)
		{
			worker.shutdownNow();
		}
		ReplayRenderer oldRenderer = renderer;
		HouseIsolation oldIsolation = isolation;
		clientThread.invokeLater(() ->
		{
			try
			{
				if (oldRenderer != null)
				{
					oldRenderer.close();
				}
			}
			finally
			{
				if (oldIsolation != null)
				{
					oldIsolation.close();
				}
			}
		});
		recording = null;
		selectedScene = null;
		sourceOrigin = null;
		house = loading = false;
		clock.load(0, System.nanoTime());
		panel = null;
	}

	/** The Watch section; the sidebar panel adds it on the Swing thread. */
	public JComponent panel()
	{
		WatchPanel created = new WatchPanel(this);
		panel = created;
		onClient(this::publish);
		return created;
	}

	/** The plugin's own folder, the only place recordings are read from. */
	public void folder(Filepath folder) { this.folder = folder; }

	/** Opens a recording in the plugin's folder by file name. */
	public void load(String name)
	{
		Filepath where = folder;
		if (where == null)
		{
			notice("The recording folder is not ready yet.");
			return;
		}
		try
		{
			load(name, where.joinSegment(name));
		}
		catch (RuntimeException e)
		{
			notice("Could not open recording: " + e.getMessage());
		}
	}

	/** Lists the recordings in the plugin's folder, newest first, and opens the one picked. */
	void choose(Component parent)
	{
		Filepath where = folder;
		if (where == null || worker == null || worker.isShutdown())
		{
			return;
		}
		worker.execute(() ->
		{
			List<String> names;
			try
			{
				names = recordings(where);
			}
			catch (IOException | RuntimeException e)
			{
				notice("Could not list your recordings: " + e.getMessage());
				return;
			}
			SwingUtilities.invokeLater(() ->
			{
				if (names.isEmpty())
				{
					JOptionPane.showMessageDialog(parent, "No saved recordings yet. Play, then stop recording or log out.");
					return;
				}
				JComboBox<String> list = new JComboBox<>(names.toArray(new String[0]));
				if (JOptionPane.showConfirmDialog(parent, list, "Watch a recording", JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION)
				{
					load((String) list.getSelectedItem());
				}
			});
		});
	}

	static List<String> recordings(Filepath folder) throws IOException
	{
		try (Stream<Filepath> files = folder.walk(1))
		{
			return files.filter(f -> f.getFileName().endsWith(".embertide") || f.getFileName().endsWith(".mccr"))
				.sorted(Comparator.comparing(Viewer::modified).reversed()).map(Filepath::getFileName)
				.collect(Collectors.toList());
		}
	}

	private static long modified(Filepath file)
	{
		try
		{
			return file.getLastModifiedTime().toMillis();
		}
		catch (IOException e)
		{
			return 0;
		}
	}

	private void load(String name, Filepath file)
	{
		if (!enabled || worker == null || worker.isShutdown())
		{
			return;
		}
		long token = generation.incrementAndGet();
		if (loadTask != null)
		{
			loadTask.cancel(true);
		}
		onClient(() ->
		{
			loading = true;
			clock.play(false, System.nanoTime());
			message = "Reading recording…";
			publish();
		});
		loadTask = worker.submit(() ->
		{
			try
			{
				Recording result = new RecordingReader().read(file);
				boolean recorded = result.scenes.stream().anyMatch(scene -> scene.terrain.recorded());
				// Snapshot cells naming an underlay or overlay become a floor near where the player walked.
				boolean cells = result.scenes.stream().anyMatch(scene -> scene.ground.values().stream().anyMatch(g -> SnapshotTerrain.names(g.material)));
				onClient(() ->
				{
					if (token != generation.get())
					{
						return;
					}
					clearProjection("Recording replaced.");
					renderer.close();
					recording = result;
					clock.load(result.duration, System.nanoTime());
					filename = name;
					loading = false;
					message = recorded ? "Loaded. In your house, press Place here or right-click a floor tile."
						: "Loaded. " + (cells ? ReplayRenderer.PARTIAL_GROUND : ReplayRenderer.NO_GROUND);
					publish();
				});
			}
			catch (Exception e)
			{
				onClient(() ->
				{
					if (token == generation.get())
					{
						loading = false;
						message = "Could not open recording: " + e.getMessage();
						publish();
					}
				});
			}
		});
	}

	void toggle()
	{
		onClient(() ->
		{
			if (renderer.placed() && !loading)
			{
				clock.play(!clock.playing(), System.nanoTime());
				publish();
			}
		});
	}

	void seek(double time)
	{
		onClient(() ->
		{
			clock.seek(time, System.nanoTime());
			draw();
			publish();
		});
	}

	void speed(double speed) { onClient(() -> clock.speed(speed, System.nanoTime())); }
	void loop(boolean loop) { onClient(() -> clock.loop(loop)); }

	void clear()
	{
		onClient(() ->
		{
			clearProjection("Replay cleared.");
			publish();
		});
	}

	void rotate()
	{
		onClient(() ->
		{
			rotation = (rotation + 1) & 3;
			replace();
		});
	}

	void hideSurroundings(boolean hide)
	{
		onClient(() ->
		{
			hideSurroundings = hide;
			if (!hide)
			{
				isolation.close();
				if (renderer.placed())
				{
					message = "House showing. Clear removes the replay.";
				}
			}
			else if (!isolation.supported())
			{
				message = isolation.problem();
			}
			else if (renderer.placed())
			{
				isolation.hide(client.getTopLevelWorldView().getScene());
				message = "Surroundings hidden. Clear restores the house.";
			}
			publish();
		});
	}

	void miniature(boolean on)
	{
		onClient(() ->
		{
			if (miniature != on)
			{
				miniature = on;
				replace();
			}
			publish();
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (EmbertideConfig.GROUP.equals(event.getGroup()) && event.getKey().startsWith("viewer"))
		{
			onClient(() ->
			{
				readConfig();
				replace();
				publish();
			});
		}
	}

	private void readConfig()
	{
		if (config == null)
		{
			return;
		}
		size = config.viewerWidth();
		radius = config.viewerRadius();
		lift = config.viewerLift();
		surroundingMap = config.viewerWiderArea();
		extraArea = config.viewerExtraArea();
		allFloors = config.viewerAllFloors();
		renderer.objectLimit(config.viewerObjectLimit());
		ground = config.viewerGround();
		scenery = config.viewerScenery();
	}

	void placeHere()
	{
		onClient(() ->
		{
			if (client.getLocalPlayer() != null)
			{
				place(client.getLocalPlayer().getLocalLocation(), true);
			}
		});
	}

	private void place(LocalPoint anchor, boolean newOrigin)
	{
		if (recording == null || loading || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		WorldView view = client.getTopLevelWorldView();
		house = HouseGate.containsHouse(view);
		if (!house || anchor == null || view == null || anchor.getWorldView() != view.getId())
		{
			message = "Go into your house to place the replay.";
			publish();
			return;
		}
		if (hideSurroundings && !isolation.supported())
		{
			message = isolation.problem();
			publish();
			return;
		}
		Recording.Scene scene = recording.sceneAt(clock.time());
		if (newOrigin || sourceOrigin == null || scene != selectedScene)
		{
			sourceOrigin = scene.origin(clock.time());
		}
		if (sourceOrigin == null)
		{
			clearProjection("This part has no recorded actors. Seek to another moment.");
			publish();
			return;
		}
		renderer.place(scene, sourceOrigin, anchor, view.getPlane(), Perspective.getTileHeight(client, anchor, view.getPlane()),
			miniature, size, radius, rotation, miniature ? lift : 0, surroundingMap, extraArea, allFloors);
		if (hideSurroundings)
		{
			isolation.hide(view.getScene());
		}
		selectedScene = scene;
		baseX = view.getBaseX();
		baseY = view.getBaseY();
		world = client.getWorld();
		message = miniature ? "Miniature placed. Press Play or scrub the timeline." : "Life-size scene placed around you. Press Play or scrub.";
		draw();
		publish();
	}

	private void replace()
	{
		if (renderer.placed())
		{
			place(anchor(), false);
		}
	}

	private LocalPoint anchor()
	{
		Placement p = renderer.placement();
		return new LocalPoint(p.anchorX, p.anchorY, p.worldView);
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (!enabled)
		{
			return;
		}
		try
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				WorldView view = client.getTopLevelWorldView();
				if (isolation.active() && (isolation.rendererChanged() || view == null || !isolation.matches(view.getScene())))
				{
					clearProjection("Renderer or scene changed. House restored; place the replay again.");
				}
				if (renderer.placed() && (view == null || view.getBaseX() != baseX || view.getBaseY() != baseY
					|| client.getWorld() != world || view.getPlane() != renderer.placement().plane))
				{
					clearProjection("House scene changed. Place the replay again.");
				}
				clock.tick(System.nanoTime());
				draw();
			}
			if (System.nanoTime() >= nextUi)
			{
				publish();
				nextUi = System.nanoTime() + 200_000_000L;
			}
		}
		catch (RuntimeException e)
		{
			LOG.warn("Embertide projection stopped", e);
			clearProjection("Projection stopped: " + e.getClass().getSimpleName() + ". See the RuneLite log.");
			publish();
		}
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		if (enabled && isolation != null && isolation.frame())
		{
			clearProjection(HouseIsolation.DID_NOT_HIDE);
			publish();
		}
	}

	private void draw()
	{
		if (recording == null || !renderer.placed() || !house)
		{
			return;
		}
		Recording.Scene now = recording.sceneAt(clock.time());
		Recording.Sample player = now.origin(clock.time());
		if (now != selectedScene || (!allFloors && player != null && sourceOrigin != null && player.plane != sourceOrigin.plane))
		{
			place(anchor(), true);
			return;
		}
		renderer.draw(recording, clock.time(), ground, scenery);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		house = HouseGate.containsHouse(client.getTopLevelWorldView());
		if (!house && renderer.placed())
		{
			clearProjection("You left your house, so the replay was cleared.");
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			house = false;
			clearProjection(renderer.placed() ? "Replay cleared. Place it again in your house." : message);
			publish();
		}
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (!house || recording == null || loading)
		{
			return;
		}
		WorldView view = client.getTopLevelWorldView();
		Tile tile = view == null ? null : view.getSelectedSceneTile();
		if (tile == null)
		{
			return;
		}
		LocalPoint at = tile.getLocalLocation();
		client.createMenuEntry(-1).setOption("Place Embertide replay").setTarget("").setType(MenuAction.RUNELITE)
			.onClick(entry -> place(at, true));
	}

	private void clearProjection(String notice)
	{
		try
		{
			if (renderer != null)
			{
				renderer.clear();
			}
		}
		finally
		{
			if (isolation != null)
			{
				isolation.close();
			}
			clock.play(false, System.nanoTime());
			selectedScene = null;
			sourceOrigin = null;
			message = notice;
		}
	}

	private void notice(String text)
	{
		onClient(() ->
		{
			message = text;
			publish();
		});
	}

	private void onClient(Runnable task)
	{
		long epoch = lifecycle.get();
		if (!enabled)
		{
			return;
		}
		clientThread.invokeLater(() ->
		{
			if (!enabled || epoch != lifecycle.get())
			{
				return;
			}
			try
			{
				task.run();
			}
			catch (RuntimeException e)
			{
				LOG.warn("Embertide viewer action failed", e);
				clearProjection("Viewer action failed: " + e.getClass().getSimpleName() + ". See the RuneLite log.");
				publish();
			}
		});
	}

	private void publish()
	{
		WatchPanel current = panel;
		if (current == null)
		{
			return;
		}
		String file = filename, notice = message;
		String detail = recording == null ? "" : recording.scenes.size() + " recorded scene(s)"
			+ (recording.revision != client.getRevision() ? " · recorded cache " + recording.revision + ", current " + client.getRevision() : "")
			+ (renderer.placed() ? "\n" + renderer.status() : "");
		double elapsed = clock.time(), total = clock.duration();
		boolean playing = clock.playing(), ready = recording != null, placed = renderer.placed(), inHouse = house, busy = loading;
		SwingUtilities.invokeLater(() ->
		{
			if (enabled && current == panel)
			{
				current.update(file, notice, detail, elapsed, total, playing, ready, placed, inHouse, busy);
			}
		});
	}
}

package com.extrinsiccognition.embertide.viewer;

import com.extrinsiccognition.embertide.MccrFileRecorder;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSlider;
import javax.swing.JTextArea;
import javax.swing.text.DefaultCaret;
import net.runelite.client.util.LinkBrowser;

/** The sidebar's Watch tab. Tuning lives in the plugin's settings. */
final class WatchPanel extends JPanel
{
	private final JTextArea file = text("Pick a recording to watch in your player-owned house.");
	private final JTextArea status = text("");
	private final JButton play = new JButton("Play");
	private final JButton place = new JButton("Place here");
	private final JButton clear = new JButton("Clear");
	private final JSlider seek = new JSlider(0, 10000, 0);
	private final JLabel time = new JLabel("0:00 / 0:00");
	private boolean updating;
	private double duration;

	WatchPanel(Viewer viewer)
	{
		setOpaque(false);
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		JButton load = new JButton("Open recording…"), rotate = new JButton("Rotate 90°"), restart = new JButton("Restart");
		JComboBox<String> mode = new JComboBox<>(new String[]{"Miniature", "Life size"});
		JComboBox<String> speed = new JComboBox<>(new String[]{"0.25×", "0.5×", "1×", "2×", "4×"});
		speed.setSelectedIndex(2);
		JCheckBox loop = new JCheckBox("Loop", true), isolate = new JCheckBox("Hide surroundings", true);
		isolate.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
		isolate.setToolTipText("Hides the house, other players and pets while the replay is placed. House walls still block you. Clear puts them back.");
		JTextArea hint = text("More options in the plugin's settings.");
		hint.setForeground(new Color(170, 170, 170));
		JTextArea more = text("Studio, in your browser, cuts clips, changes the look and makes share links.");
		JButton studio = new JButton("Open Studio");
		studio.setToolTipText("Opens Studio in your browser. Drag a recording from your recordings folder into it.");
		for (JComponent c : new JComponent[]{load, file, mode, pair(place, clear), rotate, seek, time, pair(play, restart), pair(speed, loop), isolate, status, hint, more, studio})
		{
			c.setAlignmentX(LEFT_ALIGNMENT);
			if (!(c instanceof JTextArea))
			{
				c.setMaximumSize(new Dimension(Integer.MAX_VALUE, Math.max(26, c.getPreferredSize().height)));
			}
			add(c);
			add(Box.createVerticalStrut(8));
		}
		load.addActionListener(e -> viewer.choose(this));
		studio.addActionListener(e -> LinkBrowser.browse(MccrFileRecorder.STUDIO_URL));
		play.addActionListener(e -> viewer.toggle());
		place.addActionListener(e -> viewer.placeHere());
		clear.addActionListener(e -> viewer.clear());
		rotate.addActionListener(e -> viewer.rotate());
		restart.addActionListener(e -> viewer.seek(0));
		seek.addChangeListener(e ->
		{
			if (!updating && !seek.getValueIsAdjusting())
			{
				viewer.seek(duration * seek.getValue() / 10000.0);
			}
		});
		speed.addActionListener(e -> viewer.speed(new double[]{.25, .5, 1, 2, 4}[speed.getSelectedIndex()]));
		loop.addActionListener(e -> viewer.loop(loop.isSelected()));
		mode.addActionListener(e -> viewer.miniature(mode.getSelectedIndex() == 0));
		isolate.addActionListener(e -> viewer.hideSurroundings(isolate.isSelected()));
		place.setEnabled(false);
		play.setEnabled(false);
		clear.setEnabled(false);
		seek.setEnabled(false);
	}

	void update(String filename, String message, String detail, double elapsed, double total,
		boolean playing, boolean ready, boolean placed, boolean house, boolean loading)
	{
		if (!filename.isEmpty())
		{
			int extension = filename.lastIndexOf('.');
			setText(file, filename.length() > 64 ? filename.substring(0, 42) + "..." + (extension > 42 ? filename.substring(extension) : "") : filename);
			if (!filename.equals(file.getToolTipText()))
			{
				file.setToolTipText(filename);
			}
		}
		setText(status, message.isEmpty() || detail.isEmpty() ? message + detail : message + "\n" + detail);
		duration = total;
		String playText = playing ? "Pause" : "Play";
		if (!playText.equals(play.getText()))
		{
			play.setText(playText);
		}
		play.setEnabled(ready && placed && !loading);
		place.setEnabled(ready && house && !loading);
		clear.setEnabled(placed);
		seek.setEnabled(ready && !loading);
		String timeText = format(elapsed) + " / " + format(total);
		if (!timeText.equals(time.getText()))
		{
			time.setText(timeText);
		}
		if (!seek.getValueIsAdjusting())
		{
			updating = true;
			seek.setValue(total <= 0 ? 0 : (int) Math.round(10000 * elapsed / total));
			updating = false;
		}
	}

	static String format(double seconds)
	{
		int s = (int) Math.max(0, seconds);
		return String.format("%d:%02d", s / 60, s % 60);
	}

	private static void setText(JTextArea area, String content)
	{
		if (!content.equals(area.getText()))
		{
			area.setText(content);
		}
	}

	private static JPanel pair(JComponent left, JComponent right)
	{
		JPanel row = new JPanel(new GridLayout(1, 2, 6, 0));
		row.setOpaque(false);
		row.add(left);
		row.add(right);
		return row;
	}

	private static JTextArea text(String content)
	{
		// Height follows the content, never a fixed row count.
		JTextArea area = new JTextArea(content)
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setEditable(false);
		// A read-only JTextArea still has a caret, and its default policy scrolls the sidebar on setText().
		((DefaultCaret) area.getCaret()).setUpdatePolicy(DefaultCaret.NEVER_UPDATE);
		area.setFocusable(false);
		area.setOpaque(false);
		area.setFont(new JLabel().getFont());
		area.setColumns(20);
		area.setBorder(BorderFactory.createEmptyBorder());
		return area;
	}
}

